        if all((x.is_Atom for x in expr.args)):
            tex = '\\varepsilon_{%s}' % ' '.join(indices)
        else:
            tex = '\\varepsilon_{%s}' % ', '.join(indices)
        if exp:
            tex = '\\left(%s\\right)^{%s}' % (tex, exp)
