            tex1 = 'B_{%s, %s}' % (self._print(expr.args[0]), self._print(expr.args[1]))
            tex2 = '\\left(%s\\right)' % ', '.join((self._print(el) for el in expr.args[2]))
            if exp is not None:
                tex = '%s^{%s}%s' % (tex1, exp, tex2)
            else:
                tex = tex1 + tex2
            return tex
        return self.__print_number_polynomial(expr, 'B', exp)

