            return '\\left(\\phi\\left(%s\\right)\\right)^{%s}' % (self._print(expr.args[0]), exp)
        return '\\phi\\left(%s\\right)' % self._print(expr.args[0])

    def _print_reduced_totient(self, expr, exp=None):
