            return '\\left(\\lambda\\left(%s\\right)\\right)^{%s}' % (self._print(expr.args[0]), exp)
        return '\\lambda\\left(%s\\right)' % self._print(expr.args[0])

    def _print_divisor_sigma(self, expr, exp=None):
