    def _print_primenu(self, expr, exp=None):
        if exp is not None:
            return '\\left(\\nu\\left(%s\\right)\\right)^{%s}' % (self._print(expr.args[0]), exp)
        return '\\nu\\left(%s\\right)' % self._print(expr.args[0])

    def _print_primeomega(self, expr, exp=None):
