    _kf = _numpy_known_functions
    _kc = _numpy_known_constants

    def __init__(self, settings=None):
        self.language = 'Python with {}'.format(self._module)
        self.printmethod = '_{}code'.format(self._module)
        self._kf = {**PythonCodePrinter._kf, **self._kf}
        super().__init__(settings=settings)

    def _print_seq(self, seq):
        delimiter = ', '
        return '({},)'.format(delimiter.join((self._print(item) for item in seq)))

    def _print_NegativeInfinity(self, expr):
        return '-' + self._print(S.Infinity)

    def _print_MatMul(self, expr):
        if expr.as_coeff_matrices()[0] is not S.One:
            expr_list = expr.as_coeff_matrices()[1] + [expr.as_coeff_matrices()[0]]
            return '({})'.format(').dot('.join((self._print(i) for i in expr_list)))
        return '({})'.format(').dot('.join((self._print(i) for i in expr.args)))

    def _print_MatPow(self, expr):
        return '{}({}, {})'.format(self._module_format(self._module + '.linalg.matrix_power'), self._print(expr.args[0]), self._print(expr.args[1]))

    def _print_Inverse(self, expr):
        return '{}({})'.format(self._module_format(self._module + '.linalg.inv'), self._print(expr.args[0]))

    def _print_DotProduct(self, expr):
        arg1, arg2 = expr.args
        if arg1.shape[0] != 1:
            arg1 = arg1.T
        if arg2.shape[1] != 1:
            arg2 = arg2.T
        return '%s(%s, %s)' % (self._module_format(self._module + '.dot'), self._print(arg1), self._print(arg2))

    def _print_MatrixSolve(self, expr):
        return '%s(%s, %s)' % (self._module_format(self._module + '.linalg.solve'), self._print(expr.matrix), self._print(expr.vector))

    def _print_ZeroMatrix(self, expr):
        return '{}({})'.format(self._module_format(self._module + '.zeros'), self._print(expr.shape))

    def _print_OneMatrix(self, expr):
        return '{}({})'.format(self._module_format(self._module + '.ones'), self._print(expr.shape))

    def _print_FunctionMatrix(self, expr):
        from sympy.abc import i, j
        lamda = expr.lamda
        if not isinstance(lamda, Lambda):
            lamda = Lambda((i, j), lamda(i, j))
        return '{}(lambda {}: {}, {})'.format(self._module_format(self._module + '.fromfunction'), ', '.join((self._print(arg) for arg in lamda.args[0])), self._print(lamda.args[1]), self._print(expr.shape))

