    def _print_FracField(self, field):
        return '%s(%s, %s, %s)' % (field.__class__.__name__, self._print(field.symbols), self._print(field.domain), self._print(field.order))

    def _print_PolyElement(self, poly):
        terms = list(poly.terms())
