tensorflow = import_module('tensorflow')

class TensorflowPrinter(ArrayPrinter, AbstractPythonCodePrinter):
    printmethod = '_tensorflowcode'
    mapping = {sympy.Abs: 'tensorflow.math.abs', sympy.sign: 'tensorflow.math.sign', sympy.ceiling: 'tensorflow.math.ceil', sympy.floor: 'tensorflow.math.floor', sympy.log: 'tensorflow.math.log', sympy.exp: 'tensorflow.math.exp', Sqrt: 'tensorflow.math.sqrt', sympy.cos: 'tensorflow.math.cos', sympy.acos: 'tensorflow.math.acos', sympy.sin: 'tensorflow.math.sin', sympy.asin: 'tensorflow.math.asin', sympy.tan: 'tensorflow.math.tan', sympy.atan: 'tensorflow.math.atan', sympy.atan2: 'tensorflow.math.atan2', sympy.cosh: 'tensorflow.math.cosh', sympy.acosh: 'tensorflow.math.acosh', sympy.sinh: 'tensorflow.math.sinh', sympy.asinh: 'tensorflow.math.asinh', sympy.tanh: 'tensorflow.math.tanh', sympy.atanh: 'tensorflow.math.atanh', sympy.re: 'tensorflow.math.real', sympy.im: 'tensorflow.math.imag', sympy.arg: 'tensorflow.math.angle', sympy.erf: 'tensorflow.math.erf', sympy.loggamma: 'tensorflow.math.lgamma', sympy.Eq: 'tensorflow.math.equal', sympy.Ne: 'tensorflow.math.not_equal', sympy.StrictGreaterThan: 'tensorflow.math.greater', sympy.StrictLessThan: 'tensorflow.math.less', sympy.LessThan: 'tensorflow.math.less_equal', sympy.GreaterThan: 'tensorflow.math.greater_equal', sympy.And: 'tensorflow.math.logical_and', sympy.Or: 'tensorflow.math.logical_or', sympy.Not: 'tensorflow.math.logical_not', sympy.Max: 'tensorflow.math.maximum', sympy.Min: 'tensorflow.math.minimum', sympy.MatAdd: 'tensorflow.math.add', sympy.HadamardProduct: 'tensorflow.math.multiply', sympy.Trace: 'tensorflow.linalg.trace', sympy.Determinant: 'tensorflow.linalg.det'}
    _default_settings = dict(AbstractPythonCodePrinter._default_settings, tensorflow_version=None)

    def __init__(self, settings=None):
        super().__init__(settings)
        version = self._settings['tensorflow_version']
        if version is None and tensorflow:
            version = tensorflow.__version__
        self.tensorflow_version = version

    def _print_Function(self, expr):
        op = self.mapping.get(type(expr), None)
        if op is None:
            return super()._print_Basic(expr)
        children = [self._print(arg) for arg in expr.args]
        if len(children) == 1:
            return '%s(%s)' % (self._module_format(op), children[0])
        else:
            return self._expand_fold_binary_op(op, children)
