    def _print_Add(self, expr, order=None):
        terms = self._as_ordered_terms(expr, order=order)
        pforms, indices = ([], [])

        def pretty_negative(pform, index):
            if index == 0:
                if pform.height() > 1:
                    pform_neg = '- '
                else:
                    pform_neg = '-'
            else:
                pform_neg = ' - '
            if pform.binding > prettyForm.NEG or pform.binding == prettyForm.ADD:
                p = stringPict(*pform.parens())
            else:
                p = pform
            p = stringPict.next(pform_neg, p)
            return prettyForm(*p, binding=prettyForm.NEG)
        for i, term in enumerate(terms):
            if term.is_Mul and term.could_extract_minus_sign():
                coeff, other = term.as_coeff_mul(rational=False)
                if coeff == -1:
                    negterm = Mul(*other, evaluate=False)
                else:
                    negterm = Mul(-coeff, *other, evaluate=False)
                pform = self._print(negterm)
                pforms.append(pretty_negative(pform, i))
            elif term.is_Rational and term.q > 1:
                pforms.append(None)
                indices.append(i)
            elif term.is_Number and term < 0:
                pform = self._print(-term)
                pforms.append(pretty_negative(pform, i))
            elif term.is_Relational:
                pforms.append(prettyForm(*self._print(term).parens()))
            else:
                pforms.append(self._print(term))
        if indices:
            large = True
            for pform in pforms:
                if pform is not None and pform.height() > 1:
                    break
            else:
                large = False
            for i in indices:
                term, negative = (terms[i], False)
                if term < 0:
                    term, negative = (-term, True)
                if large:
                    pform = prettyForm(str(term.p)) / prettyForm(str(term.q))
                else:
                    pform = self._print(term)
                if negative:
                    pform = pretty_negative(pform, i)
                pforms[i] = pform
        return prettyForm.__add__(*pforms)

    def _print_Mul(self, product):
        from sympy.physics.units import Quantity
        args = product.args
        if args[0] is S.One or any((isinstance(arg, Number) for arg in args[1:])):
            strargs = list(map(self._print, args))
            negone = strargs[0] == '-1'
            if negone:
                strargs[0] = prettyForm('1', 0, 0)
            obj = prettyForm.__mul__(*strargs)
            if negone:
                obj = prettyForm('-' + obj.s, obj.baseline, obj.binding)
            return obj
        a = []
        b = []
        if self.order not in ('old', 'none'):
            args = product.as_ordered_factors()
        else:
            args = list(product.args)
        args = sorted(args, key=lambda x: isinstance(x, Quantity) or (isinstance(x, Pow) and isinstance(x.base, Quantity)))
        for item in args:
            if item.is_commutative and item.is_Pow and item.exp.is_Rational and item.exp.is_negative:
                if item.exp != -1:
                    b.append(Pow(item.base, -item.exp, evaluate=False))
                else:
                    b.append(Pow(item.base, -item.exp))
            elif item.is_Rational and item is not S.Infinity:
                if item.p != 1:
                    a.append(Rational(item.p))
                if item.q != 1:
                    b.append(Rational(item.q))
            else:
                a.append(item)
        a = [self._print(ai) for ai in a]
        b = [self._print(bi) for bi in b]
        if len(b) == 0:
            return prettyForm.__mul__(*a)
        else:
            if len(a) == 0:
                a.append(self._print(S.One))
            return prettyForm.__mul__(*a) / prettyForm.__mul__(*b)

    def _print_nth_root(self, base, root):
        bpretty = self._print(base)
        if self._settings['use_unicode_sqrt_char'] and self._use_unicode and (root == 2) and (bpretty.height() == 1) and (bpretty.width() == 1 or (base.is_Integer and base.is_nonnegative)):
            return prettyForm(*bpretty.left(nth_root[2]))
        _zZ = xobj('/', 1)
        rootsign = xobj('\\', 1) + _zZ
        rpretty = self._print(root)
        if rpretty.height() != 1:
            return self._print(base) ** self._print(1 / root)
        exp = '' if root == 2 else str(rpretty).ljust(2)
        if len(exp) > 2:
            rootsign = ' ' * (len(exp) - 2) + rootsign
        rootsign = stringPict(exp + '\n' + rootsign)
        rootsign.baseline = 0
        linelength = bpretty.height() - 1
        diagonal = stringPict('\n'.join((' ' * (linelength - i - 1) + _zZ + ' ' * i for i in range(linelength))))
        diagonal.baseline = linelength - 1
        rootsign = prettyForm(*rootsign.right(diagonal))
        rootsign.baseline = max(1, bpretty.baseline)
        s = prettyForm(hobj('_', 2 + bpretty.width()))
        s = prettyForm(*bpretty.above(s))
        s = prettyForm(*s.left(rootsign))
        return s

    def _print_Pow(self, power):
        from sympy.simplify.simplify import fraction
        b, e = power.as_base_exp()
        if power.is_commutative:
            if e is S.NegativeOne:
                return prettyForm('1') / self._print(b)
            n, d = fraction(e)
            if n is S.One and d.is_Atom and (not e.is_Integer) and (e.is_Rational or d.is_Symbol) and self._settings['root_notation']:
                return self._print_nth_root(b, d)
            if e.is_Rational and e < 0:
                return prettyForm('1') / self._print(Pow(b, -e, evaluate=False))
        if b.is_Relational:
            return prettyForm(*self._print(b).parens()).__pow__(self._print(e))
        return self._print(b) ** self._print(e)

    def _print_UnevaluatedExpr(self, expr):
        return self._print(expr.args[0])

    def __print_numer_denom(self, p, q):
        if q == 1:
            if p < 0:
                return prettyForm(str(p), binding=prettyForm.NEG)
            else:
                return prettyForm(str(p))
        elif abs(p) >= 10 and abs(q) >= 10:
            if p < 0:
                return prettyForm(str(p), binding=prettyForm.NEG) / prettyForm(str(q))
            else:
                return prettyForm(str(p)) / prettyForm(str(q))
        else:
            return None

    def _print_Rational(self, expr):
        result = self.__print_numer_denom(expr.p, expr.q)
        if result is not None:
            return result
        else:
            return self.emptyPrinter(expr)

    def _print_Fraction(self, expr):
        result = self.__print_numer_denom(expr.numerator, expr.denominator)
        if result is not None:
            return result
        else:
            return self.emptyPrinter(expr)

    def _print_ProductSet(self, p):
        if len(p.sets) >= 1 and (not has_variety(p.sets)):
            return self._print(p.sets[0]) ** self._print(len(p.sets))
        else:
            prod_char = pretty_atom('Multiplication') if self._use_unicode else 'x'
            return self._print_seq(p.sets, None, None, ' %s ' % prod_char, parenthesize=lambda set: set.is_Union or set.is_Intersection or set.is_ProductSet)

    def _print_FiniteSet(self, s):
        items = sorted(s.args, key=default_sort_key)
        return self._print_seq(items, '{', '}', ', ')

    def _print_Range(self, s):
        if self._use_unicode:
            dots = pretty_atom('Dots')
        else:
            dots = '...'
        if s.start.is_infinite and s.stop.is_infinite:
            if s.step.is_positive:
                printset = (dots, -1, 0, 1, dots)
            else:
                printset = (dots, 1, 0, -1, dots)
        elif s.start.is_infinite:
            printset = (dots, s[-1] - s.step, s[-1])
        elif s.stop.is_infinite:
            it = iter(s)
            printset = (next(it), next(it), dots)
        elif len(s) > 4:
            it = iter(s)
            printset = (next(it), next(it), dots, s[-1])
        else:
            printset = tuple(s)
        return self._print_seq(printset, '{', '}', ', ')

    def _print_Interval(self, i):
        if i.start == i.end:
            return self._print_seq(i.args[:1], '{', '}')
        else:
            if i.left_open:
                left = '('
            else:
                left = '['
            if i.right_open:
                right = ')'
            else:
                right = ']'
            return self._print_seq(i.args[:2], left, right)

    def _print_AccumulationBounds(self, i):
        left = '<'
        right = '>'
        return self._print_seq(i.args[:2], left, right)

    def _print_Intersection(self, u):
        delimiter = ' %s ' % pretty_atom('Intersection', 'n')
        return self._print_seq(u.args, None, None, delimiter, parenthesize=lambda set: set.is_ProductSet or set.is_Union or set.is_Complement)

    def _print_Union(self, u):
        union_delimiter = ' %s ' % pretty_atom('Union', 'U')
        return self._print_seq(u.args, None, None, union_delimiter, parenthesize=lambda set: set.is_ProductSet or set.is_Intersection or set.is_Complement)

    def _print_SymmetricDifference(self, u):
        if not self._use_unicode:
            raise NotImplementedError('ASCII pretty printing of SymmetricDifference is not implemented')
        sym_delimeter = ' %s ' % pretty_atom('SymmetricDifference')
        return self._print_seq(u.args, None, None, sym_delimeter)

    def _print_Complement(self, u):
        delimiter = ' \\ '
        return self._print_seq(u.args, None, None, delimiter, parenthesize=lambda set: set.is_ProductSet or set.is_Intersection or set.is_Union)

    def _print_ImageSet(self, ts):
        if self._use_unicode:
            inn = pretty_atom('SmallElementOf')
        else:
            inn = 'in'
        fun = ts.lamda
        sets = ts.base_sets
        signature = fun.signature
        expr = self._print(fun.expr)
        if len(signature) == 1:
            S = self._print_seq((signature[0], inn, sets[0]), delimiter=' ')
            return self._hprint_vseparator(expr, S, left='{', right='}', ifascii_nougly=True, delimiter=' ')
        else:
            pargs = tuple((j for var, setv in zip(signature, sets) for j in (var, ' ', inn, ' ', setv, ', ')))
            S = self._print_seq(pargs[:-1], delimiter='')
            return self._hprint_vseparator(expr, S, left='{', right='}', ifascii_nougly=True, delimiter=' ')

    def _print_ConditionSet(self, ts):
        if self._use_unicode:
            inn = pretty_atom('SmallElementOf')
            _and = pretty_atom('And')
        else:
            inn = 'in'
            _and = 'and'
        variables = self._print_seq(Tuple(ts.sym))
        as_expr = getattr(ts.condition, 'as_expr', None)
        if as_expr is not None:
            cond = self._print(ts.condition.as_expr())
        else:
            cond = self._print(ts.condition)
            if self._use_unicode:
                cond = self._print(cond)
                cond = prettyForm(*cond.parens())
        if ts.base_set is S.UniversalSet:
            return self._hprint_vseparator(variables, cond, left='{', right='}', ifascii_nougly=True, delimiter=' ')
        base = self._print(ts.base_set)
        C = self._print_seq((variables, inn, base, _and, cond), delimiter=' ')
        return self._hprint_vseparator(variables, C, left='{', right='}', ifascii_nougly=True, delimiter=' ')

    def _print_ComplexRegion(self, ts):
        if self._use_unicode:
            inn = pretty_atom('SmallElementOf')
        else:
            inn = 'in'
        variables = self._print_seq(ts.variables)
        expr = self._print(ts.expr)
        prodsets = self._print(ts.sets)
        C = self._print_seq((variables, inn, prodsets), delimiter=' ')
        return self._hprint_vseparator(expr, C, left='{', right='}', ifascii_nougly=True, delimiter=' ')

    def _print_Contains(self, e):
        var, set = e.args
        if self._use_unicode:
            el = f" {pretty_atom('ElementOf')} "
            return prettyForm(*stringPict.next(self._print(var), el, self._print(set)), binding=8)
        else:
            return prettyForm(sstr(e))

    def _print_FourierSeries(self, s):
        if s.an.formula is S.Zero and s.bn.formula is S.Zero:
            return self._print(s.a0)
        if self._use_unicode:
            dots = pretty_atom('Dots')
        else:
            dots = '...'
        return self._print_Add(s.truncate()) + self._print(dots)

