from sympy.core.singleton import S
from sympy.core.symbol import Symbol
from sympy.polys.polytools import lcm
from sympy.utilities import public

@public
def approximants(l, X=Symbol('x'), simplify=False):
    from sympy.simplify import simplify as simp
    from sympy.simplify.radsimp import denom
    p1, q1 = ([S.One], [S.Zero])
    p2, q2 = ([S.Zero], [S.One])
    while len(l):
        b = 0
        while l[b] == 0:
            b += 1
            if b == len(l):
                return
        m = [S.One / l[b]]
        for k in range(b + 1, len(l)):
            s = 0
            for j in range(b, k):
                s -= l[j + 1] * m[b - j - 1]
            m.append(s / l[b])
        l = m
        a, l[0] = (l[0], 0)
        p = [0] * max(len(p2), b + len(p1))
        q = [0] * max(len(q2), b + len(q1))
        for k in range(len(p2)):
            p[k] = a * p2[k]
        for k in range(b, b + len(p1)):
            p[k] += p1[k - b]
        for k in range(len(q2)):
            q[k] = a * q2[k]
        for k in range(b, b + len(q1)):
            q[k] += q1[k - b]
        while p[-1] == 0:
            p.pop()
        while q[-1] == 0:
            q.pop()
        p1, p2 = (p2, p)
        q1, q2 = (q2, q)
        c = 1
        for x in p:
            c = lcm(c, denom(x))
        for x in q:
            c = lcm(c, denom(x))
        out = sum((c * e * X ** k for k, e in enumerate(p))) / sum((c * e * X ** k for k, e in enumerate(q)))
        if simplify:
            yield simp(out)
        else:
            yield out
    return

