@timeit
def sign(e, x):
    if not isinstance(e, Basic):
        raise TypeError('e should be an instance of Basic')
    if e.is_positive:
        return 1
    elif e.is_negative:
        return -1
    elif e.is_zero:
        return 0
    elif not e.has(x):
        from sympy.simplify import logcombine
        e = logcombine(e)
        return _sign(e)
    elif e == x:
        return 1
    elif e.is_Mul:
        a, b = e.as_two_terms()
        sa = sign(a, x)
        if not sa:
            return 0
        return sa * sign(b, x)
    elif isinstance(e, exp):
        return 1
    elif e.is_Pow:
        if e.base == S.Exp1:
            return 1
        s = sign(e.base, x)
        if s == 1:
            return 1
        if e.exp.is_Integer:
            return s ** e.exp
    elif isinstance(e, log):
        return sign(e.args[0] - 1, x)
    c0, e0 = mrv_leadterm(e, x)
    return sign(c0, x)

