@cacheit
def mrv_leadterm(e, x):
    Omega = SubsSet()
    if not e.has(x):
        return (e, S.Zero)
    if Omega == SubsSet():
        Omega, exps = mrv(e, x)
    if not Omega:
        return (exps, S.Zero)
    if x in Omega:
        Omega_up = moveup2(Omega, x)
        exps_up = moveup([exps], x)[0]
        Omega = Omega_up
        exps = exps_up
    w = Dummy('w', positive=True)
    f, logw = rewrite(exps, Omega, x, w)
    try:
        lt = f.leadterm(w, logx=logw)
    except (NotImplementedError, PoleError, ValueError):
        n0 = 1
        _series = Order(1)
        incr = S.One
        while _series.is_Order:
            _series = f._eval_nseries(w, n=n0 + incr, logx=logw)
            incr *= 2
        series = _series.expand().removeO()
        try:
            lt = series.leadterm(w, logx=logw)
        except (NotImplementedError, PoleError, ValueError):
            lt = f.as_coeff_exponent(w)
            if lt[0].has(w):
                base = f.as_base_exp()[0].as_coeff_exponent(w)
                ex = f.as_base_exp()[1]
                lt = (base[0] ** ex, base[1] * ex)
    return (lt[0].subs(log(w), logw), lt[1])

def build_expression_tree(Omega, rewrites):

    class Node:

        def __init__(self):
            self.before = []
            self.expr = None
            self.var = None

        def ht(self):
            return reduce(lambda x, y: x + y, [x.ht() for x in self.before], 1)
    nodes = {}
    for expr, v in Omega:
        n = Node()
        n.var = v
        n.expr = expr
        nodes[v] = n
    for _, v in Omega:
        if v in rewrites:
            n = nodes[v]
            r = rewrites[v]
            for _, v2 in Omega:
                if r.has(v2):
                    n.before.append(nodes[v2])
    return nodes

