@timeit
def rewrite(e, Omega, x, wsym):
    from sympy import AccumBounds
    if not isinstance(Omega, SubsSet):
        raise TypeError('Omega should be an instance of SubsSet')
    if len(Omega) == 0:
        raise ValueError('Length cannot be 0')
    for t in Omega.keys():
        if not isinstance(t, exp):
            raise ValueError('Value should be exp')
    rewrites = Omega.rewrites
    Omega = list(Omega.items())
    nodes = build_expression_tree(Omega, rewrites)
    Omega.sort(key=lambda x: nodes[x[1]].ht(), reverse=True)
    for g, _ in Omega:
        sig = sign(g.exp, x)
        if sig != 1 and sig != -1 and (not sig.has(AccumBounds)):
            raise NotImplementedError('Result depends on the sign of %s' % sig)
    if sig == 1:
        wsym = 1 / wsym
    O2 = []
    denominators = []
    for f, var in Omega:
        c = limitinf(f.exp / g.exp, x)
        if c.is_Rational:
            denominators.append(c.q)
        arg = f.exp
        if var in rewrites:
            if not isinstance(rewrites[var], exp):
                raise ValueError('Value should be exp')
            arg = rewrites[var].args[0]
        O2.append((var, exp((arg - c * g.exp).expand()) * wsym ** c))
    from sympy.simplify.powsimp import powsimp
    f = powsimp(e, deep=True, combine='exp')
    for a, b in O2:
        f = f.xreplace({a: b})
    for _, var in Omega:
        assert not f.has(var)
    logw = g.exp
    if sig == 1:
        logw = -logw
    exponent = reduce(ilcm, denominators, 1)
    f = f.subs({wsym: wsym ** exponent})
    logw /= exponent
    f = bottom_up(f, lambda w: getattr(w, 'normal', lambda: w)())
    f = expand_mul(f)
    return (f, logw)

def gruntz(e, z, z0, dir='+'):
    if not z.is_symbol:
        raise NotImplementedError('Second argument must be a Symbol')
    r = None
    if z0 in (oo, I * oo):
        e0 = e
    elif z0 in (-oo, -I * oo):
        e0 = e.subs(z, -z)
    elif str(dir) == '-':
        e0 = e.subs(z, z0 - 1 / z)
    elif str(dir) == '+':
        e0 = e.subs(z, z0 + 1 / z)
    else:
        raise NotImplementedError("dir must be '+' or '-'")
    r = limitinf(e0, z)
    return r.rewrite('intractable', deep=True)

