from sympy.core import S, sympify, Expr, Dummy, Add, Mul
from sympy.core.cache import cacheit
from sympy.core.containers import Tuple
from sympy.core.function import Function, PoleError, expand_power_base, expand_log
from sympy.core.sorting import default_sort_key
from sympy.functions.elementary.exponential import exp, log
from sympy.sets.sets import Complement
from sympy.utilities.iterables import uniq, is_sequence

class Order(Expr):
    is_Order = True
    __slots__ = ()

    @cacheit
    def __new__(cls, expr, *args, **kwargs):
        expr = sympify(expr)
        if not args:
            if expr.is_Order:
                variables = expr.variables
                point = expr.point
            else:
                variables = list(expr.free_symbols)
                point = [S.Zero] * len(variables)
        else:
            args = list(args if is_sequence(args) else [args])
            variables, point = ([], [])
            if is_sequence(args[0]):
                for a in args:
                    v, p = list(map(sympify, a))
                    variables.append(v)
                    point.append(p)
            else:
                variables = list(map(sympify, args))
                point = [S.Zero] * len(variables)
        if not all((v.is_symbol for v in variables)):
            raise TypeError('Variables are not symbols, got %s' % variables)
        if len(list(uniq(variables))) != len(variables):
            raise ValueError('Variables are supposed to be unique symbols, got %s' % variables)
        if expr.is_Order:
            expr_vp = dict(expr.args[1:])
            new_vp = dict(expr_vp)
            vp = dict(zip(variables, point))
            for v, p in vp.items():
                if v in new_vp.keys():
                    if p != new_vp[v]:
                        raise NotImplementedError('Mixing Order at different points is not supported.')
                else:
                    new_vp[v] = p
            if set(expr_vp.keys()) == set(new_vp.keys()):
                return expr
            else:
                variables = list(new_vp.keys())
                point = [new_vp[v] for v in variables]
        if expr is S.NaN:
            return S.NaN
        if any((x in p.free_symbols for x in variables for p in point)):
            raise ValueError('Got %s as a point.' % point)
        if variables:
            if any((p != point[0] for p in point)):
                raise NotImplementedError('Multivariable orders at different points are not supported.')
            if point[0] in (S.Infinity, S.Infinity * S.ImaginaryUnit):
                s = {k: 1 / Dummy() for k in variables}
                rs = {1 / v: 1 / k for k, v in s.items()}
                ps = [S.Zero for p in point]
            elif point[0] in (S.NegativeInfinity, S.NegativeInfinity * S.ImaginaryUnit):
                s = {k: -1 / Dummy() for k in variables}
                rs = {-1 / v: -1 / k for k, v in s.items()}
                ps = [S.Zero for p in point]
            elif point[0] is not S.Zero:
                s = {k: Dummy() + point[0] for k in variables}
                rs = {(v - point[0]).together(): k - point[0] for k, v in s.items()}
                ps = [S.Zero for p in point]
            else:
                s = ()
                rs = ()
                ps = list(point)
            expr = expr.subs(s)
            if expr.is_Add:
                expr = expr.factor()
            if s:
                args = tuple([r[0] for r in rs.items()])
            else:
                args = tuple(variables)
            if len(variables) > 1:
                expr = expr.expand()
            old_expr = None
            while old_expr != expr:
                old_expr = expr
                if expr.is_Add:
                    lst = expr.extract_leading_order(args)
                    expr = Add(*[f.expr for e, f in lst])
                elif expr:
                    try:
                        expr = expr.as_leading_term(*args)
                    except PoleError:
                        if isinstance(expr, Function) or all((isinstance(arg, Function) for arg in expr.args)):
                            pass
                        else:
                            orders = []
                            pts = tuple(zip(args, ps))
                            for arg in expr.args:
                                try:
                                    lt = arg.as_leading_term(*args)
                                except PoleError:
                                    lt = arg
                                if lt not in args:
                                    order = Order(lt)
                                else:
                                    order = Order(lt, *pts)
                                orders.append(order)
                            if expr.is_Add:
                                new_expr = Order(Add(*orders), *pts)
                                if new_expr.is_Add:
                                    new_expr = Order(Add(*[a.expr for a in new_expr.args]), *pts)
                                expr = new_expr.expr
                            elif expr.is_Mul:
                                expr = Mul(*[a.expr for a in orders])
                            elif expr.is_Pow:
                                e = expr.exp
                                b = expr.base
                                expr = exp(e * log(b))
                    if expr.is_zero:
                        expr = S.Zero
                    else:
                        expr = expr.as_independent(*args, as_Add=False)[1]
                    expr = expand_power_base(expr)
                    expr = expand_log(expr)
                    if len(args) == 1:
                        x = args[0]
                        margs = list(Mul.make_args(expr.as_independent(x, as_Add=False)[1]))
                        for i, t in enumerate(margs):
                            if t.is_Pow:
                                b, q = t.args
                                if b in (x, -x) and q.is_real and (not q.has(x)):
                                    margs[i] = x ** q
                                elif b.is_Pow and (not b.exp.has(x)):
                                    b, r = b.args
                                    if b in (x, -x) and r.is_real:
                                        margs[i] = x ** (r * q)
                                elif b.is_Mul and b.args[0] is S.NegativeOne:
                                    b = -b
                                    if b.is_Pow and (not b.exp.has(x)):
                                        b, r = b.args
                                        if b in (x, -x) and r.is_real:
                                            margs[i] = x ** (r * q)
                        expr = Mul(*margs)
            expr = expr.subs(rs)
        if expr.is_Order:
            expr = expr.expr
        if not expr.has(*variables) and (not expr.is_zero):
            expr = S.One
        vp = dict(zip(variables, point))
        variables.sort(key=default_sort_key)
        point = [vp[v] for v in variables]
        args = (expr,) + Tuple(*zip(variables, point))
        obj = Expr.__new__(cls, *args)
        return obj

    def _eval_nseries(self, x, n, logx, cdir=0):
        return self

    @property
    def expr(self):
        return self.args[0]

    @property
    def variables(self):
        if self.args[1:]:
            return tuple((x[0] for x in self.args[1:]))
        else:
            return ()

    @property
    def point(self):
        if self.args[1:]:
            return tuple((x[1] for x in self.args[1:]))
        else:
            return ()

    @property
    def free_symbols(self):
        return self.expr.free_symbols | set(self.variables)

    def _eval_power(b, e):
        if e.is_Number and e.is_nonnegative:
            return b.func(b.expr ** e, *b.args[1:])
        if e == O(1):
            return b
        return

    def as_expr_variables(self, order_symbols):
        if order_symbols is None:
            order_symbols = self.args[1:]
        else:
            if not all((o[1] == order_symbols[0][1] for o in order_symbols)) and (not all((p == self.point[0] for p in self.point))):
                raise NotImplementedError('Order at points other than 0 or oo not supported, got %s as a point.' % self.point)
            if order_symbols and order_symbols[0][1] != self.point[0]:
                raise NotImplementedError('Multiplying Order at different points is not supported.')
            order_symbols = dict(order_symbols)
            for s, p in dict(self.args[1:]).items():
                if s not in order_symbols.keys():
                    order_symbols[s] = p
            order_symbols = sorted(order_symbols.items(), key=lambda x: default_sort_key(x[0]))
        return (self.expr, tuple(order_symbols))

    def removeO(self):
        return S.Zero

    def getO(self):
        return self

    @cacheit
    def contains(self, expr):
        expr = sympify(expr)
        if expr.is_zero:
            return True
        if expr is S.NaN:
            return False
        point = self.point[0] if self.point else S.Zero
        if expr.is_Order:
            if any((p != point for p in expr.point)) or any((p != point for p in self.point)):
                return None
            if expr.expr == self.expr:
                return all((x in self.args[1:] for x in expr.args[1:]))
            if expr.expr.is_Add:
                return all((self.contains(x) for x in expr.expr.args))
            if self.expr.is_Add and point.is_zero:
                return any((self.func(x, *self.args[1:]).contains(expr) for x in self.expr.args))
            if self.variables and expr.variables:
                common_symbols = tuple([s for s in self.variables if s in expr.variables])
            elif self.variables:
                common_symbols = self.variables
            else:
                common_symbols = expr.variables
            if not common_symbols:
                return None
            if self.expr.is_Pow and len(self.variables) == 1 and (self.variables == expr.variables):
                symbol = self.variables[0]
                other = expr.expr.as_independent(symbol, as_Add=False)[1]
                if other.is_Pow and other.base == symbol and (self.expr.base == symbol):
                    if point.is_zero:
                        rv = (self.expr.exp - other.exp).is_nonpositive
                    if point.is_infinite:
                        rv = (self.expr.exp - other.exp).is_nonnegative
                    if rv is not None:
                        return rv
            from sympy.simplify.powsimp import powsimp
            r = None
            ratio = self.expr / expr.expr
            ratio = powsimp(ratio, deep=True, combine='exp')
            for s in common_symbols:
                from sympy.series.limits import Limit
                l = Limit(ratio, s, point).doit(heuristics=False)
                if not isinstance(l, Limit):
                    l = l != 0
                else:
                    l = None
                if r is None:
                    r = l
                elif r != l:
                    return
            return r
        if self.expr.is_Pow and len(self.variables) == 1:
            symbol = self.variables[0]
            other = expr.as_independent(symbol, as_Add=False)[1]
            if other.is_Pow and other.base == symbol and (self.expr.base == symbol):
                if point.is_zero:
                    rv = (self.expr.exp - other.exp).is_nonpositive
                if point.is_infinite:
                    rv = (self.expr.exp - other.exp).is_nonnegative
                if rv is not None:
