class ImageSet(Set):

    def __new__(cls, flambda, *sets):
        if not isinstance(flambda, Lambda):
            raise ValueError('First argument must be a Lambda')
        signature = flambda.signature
        if len(signature) != len(sets):
            raise ValueError('Incompatible signature')
        sets = [_sympify(s) for s in sets]
        if not all((isinstance(s, Set) for s in sets)):
            raise TypeError('Set arguments to ImageSet should of type Set')
        if not all((cls._check_sig(sg, st) for sg, st in zip(signature, sets))):
            raise ValueError('Signature %s does not match sets %s' % (signature, sets))
        if flambda is S.IdentityFunction and len(sets) == 1:
            return sets[0]
        if not set(flambda.variables) & flambda.expr.free_symbols:
            is_empty = fuzzy_or((s.is_empty for s in sets))
            if is_empty == True:
                return S.EmptySet
            elif is_empty == False:
                return FiniteSet(flambda.expr)
        return Basic.__new__(cls, flambda, *sets)
    lamda = property(lambda self: self.args[0])
    base_sets = property(lambda self: self.args[1:])

    @property
    def base_set(self):
        sets = self.base_sets
        if len(sets) == 1:
            return sets[0]
        else:
            return ProductSet(*sets).flatten()

    @property
    def base_pset(self):
        return ProductSet(*self.base_sets)

    @classmethod
    def _check_sig(cls, sig_i, set_i):
        if sig_i.is_symbol:
            return True
        elif isinstance(set_i, ProductSet):
            sets = set_i.sets
            if len(sig_i) != len(sets):
                return False
            return all((cls._check_sig(ts, ps) for ts, ps in zip(sig_i, sets)))
        else:
            return True

    def __iter__(self):
        already_seen = set()
        for i in self.base_pset:
            val = self.lamda(*i)
            if val in already_seen:
                continue
            else:
                already_seen.add(val)
                yield val

    def _is_multivariate(self):
        return len(self.lamda.variables) > 1

    def _contains(self, other):
        from sympy.solvers.solveset import _solveset_multi

        def get_symsetmap(signature, base_sets):
            queue = list(zip(signature, base_sets))
            symsetmap = {}
            for sig, base_set in queue:
                if sig.is_symbol:
                    symsetmap[sig] = base_set
                elif base_set.is_ProductSet:
                    sets = base_set.sets
                    if len(sig) != len(sets):
                        raise ValueError('Incompatible signature')
                    queue.extend(zip(sig, sets))
                else:
                    return None
            return symsetmap

        def get_equations(expr, candidate):
            queue = [(expr, candidate)]
            for e, c in queue:
                if not isinstance(e, Tuple):
                    yield Eq(e, c)
                elif not isinstance(c, Tuple) or len(e) != len(c):
                    yield False
                    return
                else:
                    queue.extend(zip(e, c))
        other = _sympify(other)
        expr = self.lamda.expr
        sig = self.lamda.signature
        variables = self.lamda.variables
        base_sets = self.base_sets
        rep = {v: Dummy(v.name) for v in variables}
        variables = [v.subs(rep) for v in variables]
        sig = sig.subs(rep)
        expr = expr.subs(rep)
        equations = []
        for eq in get_equations(expr, other):
            if eq is False:
                return S.false
            equations.append(eq)
        symsetmap = get_symsetmap(sig, base_sets)
        if symsetmap is None:
            return None
        symss = (eq.free_symbols for eq in equations)
        variables = set(variables) & reduce(set.union, symss, set())
        variables = tuple(variables)
        base_sets = [symsetmap[v] for v in variables]
        solnset = _solveset_multi(equations, variables, base_sets)
        if solnset is None:
            return None
        return tfn[fuzzy_not(solnset.is_empty)]

    @property
    def is_iterable(self):
        return all((s.is_iterable for s in self.base_sets))

    def doit(self, **hints):
        from sympy.sets.setexpr import SetExpr
        f = self.lamda
        sig = f.signature
        if len(sig) == 1 and sig[0].is_symbol and isinstance(f.expr, Expr):
            base_set = self.base_sets[0]
            return SetExpr(base_set)._eval_func(f).set
        if all((s.is_FiniteSet for s in self.base_sets)):
            return FiniteSet(*(f(*a) for a in product(*self.base_sets)))
        return self

    def _kind(self):
        return SetKind(self.lamda.expr.kind)

class Range(Set):

    def __new__(cls, *args):
        if len(args) == 1:
            if isinstance(args[0], range):
                raise TypeError('use sympify(%s) to convert range to Range' % args[0])
        slc = slice(*args)
        if slc.step == 0:
            raise ValueError('step cannot be 0')
        start, stop, step = (slc.start or 0, slc.stop, slc.step or 1)
        try:
            ok = []
            for w in (start, stop, step):
                w = sympify(w)
                if w in [S.NegativeInfinity, S.Infinity] or (w.has(Symbol) and w.is_integer != False):
                    ok.append(w)
                elif not w.is_Integer:
                    if w.is_infinite:
                        raise ValueError('infinite symbols not allowed')
                    raise ValueError
                else:
                    ok.append(w)
        except ValueError:
            raise ValueError(filldedent('\n    Finite arguments to Range must be integers; `imageset` can define\n    other cases, e.g. use `imageset(i, i/10, Range(3))` to give\n    [0, 1/10, 1/5].'))
        start, stop, step = ok
        null = False
        if any((i.has(Symbol) for i in (start, stop, step))):
            dif = stop - start
            n = dif / step
            if n.is_Rational:
                if dif == 0:
                    null = True
                else:
                    n = floor(n)
                    end = start + n * step
                    if dif.is_Rational:
                        if (end - stop).is_negative:
                            end += step
                    elif (end / stop - 1).is_negative:
                        end += step
            elif n.is_extended_negative:
                null = True
            else:
                end = stop
        elif start.is_infinite:
            span = step * (stop - start)
            if span is S.NaN or span <= 0:
                null = True
            elif step.is_Integer and stop.is_infinite and (abs(step) != 1):
                raise ValueError(filldedent('\n                    Step size must be %s in this case.' % (1 if step > 0 else -1)))
            else:
                end = stop
        else:
            oostep = step.is_infinite
            if oostep:
                step = S.One if step > 0 else S.NegativeOne
            n = ceiling((stop - start) / step)
            if n <= 0:
                null = True
            elif oostep:
                step = S.One
                end = start + step
            else:
                end = start + n * step
        if null:
            start = end = S.Zero
            step = S.One
        return Basic.__new__(cls, start, end, step)
    start = property(lambda self: self.args[0])
    stop = property(lambda self: self.args[1])
    step = property(lambda self: self.args[2])

    @property
