class Interval(Set):
    is_Interval = True

    def __new__(cls, start, end, left_open=False, right_open=False):
        start = _sympify(start)
        end = _sympify(end)
        left_open = _sympify(left_open)
        right_open = _sympify(right_open)
        if not all((isinstance(a, (type(true), type(false))) for a in [left_open, right_open])):
            raise NotImplementedError('left_open and right_open can have only true/false values, got %s and %s' % (left_open, right_open))
        if fuzzy_not(fuzzy_and((i.is_extended_real for i in (start, end, end - start)))):
            raise ValueError('Non-real intervals are not supported')
        if is_lt(end, start):
            return S.EmptySet
        elif (end - start).is_negative:
            return S.EmptySet
        if end == start and (left_open or right_open):
            return S.EmptySet
        if end == start and (not (left_open or right_open)):
            if start is S.Infinity or start is S.NegativeInfinity:
                return S.EmptySet
            return FiniteSet(end)
        if start is S.NegativeInfinity:
            left_open = true
        if end is S.Infinity:
            right_open = true
        if start == S.Infinity or end == S.NegativeInfinity:
            return S.EmptySet
        return Basic.__new__(cls, start, end, left_open, right_open)

    @property
    def start(self):
        return self._args[0]

    @property
    def end(self):
        return self._args[1]

    @property
    def left_open(self):
        return self._args[2]

    @property
    def right_open(self):
        return self._args[3]

