    def _boundary(self):

        def boundary_of_set(i):
            b = self.args[i].boundary
            for j, a in enumerate(self.args):
                if j != i:
                    b = b - a.interior
            return b
        return Union(*map(boundary_of_set, range(len(self.args))))

    def _contains(self, other):
        return Or(*[s.contains(other) for s in self.args])

    def is_subset(self, other):
        return fuzzy_and((s.is_subset(other) for s in self.args))

    def as_relational(self, symbol):
        if len(self.args) == 2 and all((isinstance(i, Interval) for i in self.args)):
            a, b = self.args
            if a.sup == b.inf and a.right_open and b.left_open:
                mincond = symbol > a.inf if a.left_open else symbol >= a.inf
                maxcond = symbol < b.sup if b.right_open else symbol <= b.sup
                necond = Ne(symbol, a.sup)
                return And(necond, mincond, maxcond)
        return Or(*[i.as_relational(symbol) for i in self.args])

    @property
    def is_iterable(self):
        return all((arg.is_iterable for arg in self.args))

    def __iter__(self):
        return roundrobin(*(iter(arg) for arg in self.args))

class Intersection(Set, LatticeOp):
    is_Intersection = True

    @property
    def identity(self):
        return S.UniversalSet

    @property
    def zero(self):
        return S.EmptySet

    def __new__(cls, *args, evaluate=None):
        if evaluate is None:
            evaluate = global_parameters.evaluate
        args = list(ordered(set(_sympify(args))))
        if evaluate:
            args = list(cls._new_args_filter(args))
            return simplify_intersection(args)
        args = list(ordered(args, Set._infimum_key))
        obj = Basic.__new__(cls, *args)
        obj._argset = frozenset(args)
        return obj

    @property
    def args(self):
        return self._args

    @property
    def is_iterable(self):
        return any((arg.is_iterable for arg in self.args))

    @property
    def is_finite_set(self):
        if fuzzy_or((arg.is_finite_set for arg in self.args)):
            return True

    def _kind(self):
        kinds = tuple((arg.kind for arg in self.args if arg is not S.UniversalSet))
        if not kinds:
            return SetKind(UndefinedKind)
        elif all((i == kinds[0] for i in kinds)):
            return kinds[0]
        else:
            return SetKind()

    @property
    def _inf(self):
        raise NotImplementedError()

    @property
    def _sup(self):
        raise NotImplementedError()

    def _contains(self, other):
        return And(*[set.contains(other) for set in self.args])

    def __iter__(self):
        sets_sift = sift(self.args, lambda x: x.is_iterable)
        completed = False
        candidates = sets_sift[True] + sets_sift[None]
        finite_candidates, others = ([], [])
        for candidate in candidates:
            length = None
            try:
                length = len(candidate)
            except TypeError:
                others.append(candidate)
            if length is not None:
                finite_candidates.append(candidate)
        finite_candidates.sort(key=len)
        for s in finite_candidates + others:
            other_sets = set(self.args) - {s}
            other = Intersection(*other_sets, evaluate=False)
            completed = True
            for x in s:
                try:
                    if x in other:
                        yield x
                except TypeError:
                    completed = False
            if completed:
                return
        if not completed:
            if not candidates:
                raise TypeError('None of the constituent sets are iterable')
            raise TypeError('The computation had not completed because of the undecidable set membership is found in every candidates.')

    @staticmethod
    def _handle_finite_sets(args):
        fs_args, others = sift(args, lambda x: x.is_FiniteSet, binary=True)
        if not fs_args:
            return
        fs_sets = [set(fs) for fs in fs_args]
        all_elements = reduce(lambda a, b: a | b, fs_sets, set())
        definite = set()
        for e in all_elements:
            inall = fuzzy_and((s.contains(e) for s in args))
            if inall is True:
                definite.add(e)
            if inall is not None:
                for s in fs_sets:
                    s.discard(e)
        fs_elements = reduce(lambda a, b: a | b, fs_sets, set())
        fs_symsets = [FiniteSet(*s) for s in fs_sets]
        while fs_elements:
            for e in fs_elements:
                infs = fuzzy_and((s.contains(e) for s in fs_symsets))
                if infs is True:
                    definite.add(e)
                if infs is not None:
                    for n, s in enumerate(fs_sets):
                        if e in s:
                            s.remove(e)
                            fs_symsets[n] = FiniteSet(*s)
                    fs_elements.remove(e)
                    break
            else:
                break
        if not all(fs_sets):
            fs_sets = [set()]
        if definite:
            fs_sets = [fs | definite for fs in fs_sets]
        if fs_sets == [set()]:
            return S.EmptySet
        sets = [FiniteSet(*s) for s in fs_sets]
        all_elements = reduce(lambda a, b: a | b, fs_sets, set())
        is_redundant = lambda o: all((fuzzy_bool(o.contains(e)) for e in all_elements))
        others = [o for o in others if not is_redundant(o)]
        if others:
            rest = Intersection(*others)
            if rest is S.EmptySet:
                return S.EmptySet
            if rest.is_Intersection:
                sets.extend(rest.args)
            else:
                sets.append(rest)
        if len(sets) == 1:
            return sets[0]
        else:
            return Intersection(*sets, evaluate=False)

    def as_relational(self, symbol):
        return And(*[set.as_relational(symbol) for set in self.args])

class Complement(Set):
    is_Complement = True

    def __new__(cls, a, b, evaluate=True):
        a, b = map(_sympify, (a, b))
        if evaluate:
            return Complement.reduce(a, b)
        return Basic.__new__(cls, a, b)

    @staticmethod
    def reduce(A, B):
        if B == S.UniversalSet or A.is_subset(B):
            return S.EmptySet
        if isinstance(B, Union):
            return Intersection(*(s.complement(A) for s in B.args))
        result = B._complement(A)
        if result is not None:
            return result
        else:
            return Complement(A, B, evaluate=False)

    def _contains(self, other):
        A = self.args[0]
        B = self.args[1]
        return And(A.contains(other), Not(B.contains(other)))

    def as_relational(self, symbol):
        A, B = self.args
        A_rel = A.as_relational(symbol)
        B_rel = Not(B.as_relational(symbol))
        return And(A_rel, B_rel)

    def _kind(self):
        return self.args[0].kind

    @property
    def is_iterable(self):
        if self.args[0].is_iterable:
            return True

    @property
    def is_finite_set(self):
        A, B = self.args
        a_finite = A.is_finite_set
        if a_finite is True:
            return True
        elif a_finite is False and B.is_finite_set:
            return False

    def __iter__(self):
        A, B = self.args
        for a in A:
            if a not in B:
                yield a
            else:
                continue

