def _(f, self):
    if not self:
        return S.EmptySet
    if not isinstance(f.expr, Expr):
        return
    if self.size == 1:
        return FiniteSet(f(self[0]))
    if f is S.IdentityFunction:
        return self
    x = f.variables[0]
    expr = f.expr
    if x not in expr.free_symbols or x in expr.diff(x).free_symbols:
        return
    if self.start.is_finite:
        F = f(self.step * x + self.start)
    else:
        F = f(-self.step * x + self[-1])
    F = expand_mul(F)
    if F != expr:
        return imageset(x, F, Range(self.size))

@_set_function.register(FunctionUnion, Integers)
def _(f, self):
    expr = f.expr
    if not isinstance(expr, Expr):
        return
    n = f.variables[0]
    if expr == abs(n):
        return S.Naturals0
    c = f(0)
    fx = f(n) - c
    f_x = f(-n) - c
    neg_count = lambda e: sum((_.could_extract_minus_sign() for _ in Add.make_args(e)))
    if neg_count(f_x) < neg_count(fx):
        expr = f_x + c
    a = Wild('a', exclude=[n])
    b = Wild('b', exclude=[n])
    match = expr.match(a * n + b)
    if match and match[a] and (not match[a].atoms(Float) and (not match[b].atoms(Float))):
        a, b = (match[a], match[b])
        if a in [1, -1]:
            nonint = []
            for bi in Add.make_args(b):
                if not bi.is_integer:
                    nonint.append(bi)
            b = Add(*nonint)
        if b.is_number and a.is_real:
            br, bi = match_real_imag(b)
            if br and br.is_comparable and a.is_comparable:
                br %= a
                b = br + S.ImaginaryUnit * bi
        elif b.is_number and a.is_imaginary:
            br, bi = match_real_imag(b)
            ai = a / S.ImaginaryUnit
            if bi and bi.is_comparable and ai.is_comparable:
                bi %= ai
                b = br + S.ImaginaryUnit * bi
        expr = a * n + b
    if expr != f.expr:
        return ImageSet(Lambda(n, expr), S.Integers)

