def _(a, b):
    if fuzzy_bool(a.start < b.start):
        return False
    if fuzzy_bool(a.end > b.end):
        return False
    if b.left_open and (not a.left_open) and fuzzy_bool(Eq(a.start, b.start)):
        return False
    if b.right_open and (not a.right_open) and fuzzy_bool(Eq(a.end, b.end)):
        return False

