def as_f_sign_1(e):
    if not e.is_Add or len(e.args) != 2:
        return
    a, b = e.args
    if a in (S.NegativeOne, S.One):
        g = S.One
        if b.is_Mul and b.args[0].is_Number and (b.args[0] < 0):
            a, b = (-a, -b)
            g = -g
        return (g, b, a)
    a, b = [Factors(i) for i in e.args]
    ua, ub = a.normal(b)
    gcd = a.gcd(b).as_expr()
    if S.NegativeOne in ua.factors:
        ua = ua.quo(S.NegativeOne)
        n1 = -1
        n2 = 1
    elif S.NegativeOne in ub.factors:
        ub = ub.quo(S.NegativeOne)
        n1 = 1
        n2 = -1
    else:
        n1 = n2 = 1
    a, b = [i.as_expr() for i in (ua, ub)]
    if a is S.One:
        a, b = (b, a)
        n1, n2 = (n2, n1)
    if n1 == -1:
        gcd = -gcd
        n2 = -n2
    if b is S.One:
        return (gcd, a, n2)

def _osborne(e, d):

    def f(rv):
        if not isinstance(rv, HyperbolicFunction):
            return rv
        a = rv.args[0]
        a = a * d if not a.is_Add else Add._from_args([i * d for i in a.args])
        if isinstance(rv, sinh):
            return I * sin(a)
        elif isinstance(rv, cosh):
            return cos(a)
        elif isinstance(rv, tanh):
            return I * tan(a)
        elif isinstance(rv, coth):
            return cot(a) / I
        elif isinstance(rv, sech):
            return sec(a)
        elif isinstance(rv, csch):
            return csc(a) / I
        else:
            raise NotImplementedError('unhandled %s' % rv.func)
    return bottom_up(e, f)

def _osbornei(e, d):

    def f(rv):
        if not isinstance(rv, TrigonometricFunction):
            return rv
        const, x = rv.args[0].as_independent(d, as_Add=True)
        a = x.xreplace({d: S.One}) + const * I
        if isinstance(rv, sin):
            return sinh(a) / I
        elif isinstance(rv, cos):
            return cosh(a)
        elif isinstance(rv, tan):
            return tanh(a) / I
        elif isinstance(rv, cot):
            return coth(a) * I
        elif isinstance(rv, sec):
            return sech(a)
        elif isinstance(rv, csc):
            return csch(a) * I
        else:
            raise NotImplementedError('unhandled %s' % rv.func)
    return bottom_up(e, f)

