import itertools
from sympy.core import S
from sympy.core.sorting import default_sort_key
from sympy.polys import Poly, groebner, roots
from sympy.polys.polytools import parallel_poly_from_expr
from sympy.polys.polyerrors import ComputationFailed, PolificationFailed, CoercionFailed
from sympy.simplify import rcollect
from sympy.utilities import postfixes
from sympy.utilities.misc import filldedent

class SolveFailed(Exception):
    pass

def solve_poly_system(seq, *gens, strict=False, **args):
    try:
        polys, opt = parallel_poly_from_expr(seq, *gens, **args)
    except PolificationFailed as exc:
        raise ComputationFailed('solve_poly_system', len(seq), exc)
    if len(polys) == len(opt.gens) == 2:
        f, g = polys
        if all((i <= 2 for i in f.degree_list() + g.degree_list())):
            try:
                return solve_biquadratic(f, g, opt)
            except SolveFailed:
                pass
    return solve_generic(polys, opt, strict=strict)

def solve_biquadratic(f, g, opt):
    G = groebner([f, g])
    if len(G) == 1 and G[0].is_ground:
        return None
    if len(G) != 2:
        raise SolveFailed
    x, y = opt.gens
    p, q = G
    if not p.gcd(q).is_ground:
        raise SolveFailed
    p = Poly(p, x, expand=False)
    p_roots = [rcollect(expr, y) for expr in roots(p).keys()]
    q = q.ltrim(-1)
    q_roots = list(roots(q).keys())
    solutions = [(p_root.subs(y, q_root), q_root) for q_root, p_root in itertools.product(q_roots, p_roots)]
    return sorted(solutions, key=default_sort_key)

def solve_generic(polys, opt, strict=False):

    def _is_univariate(f):
        for monom in f.monoms():
            if any(monom[:-1]):
                return False
        return True

    def _subs_root(f, gen, zero):
        p = f.as_expr({gen: zero})
        if f.degree(gen) >= 2:
            p = p.expand(deep=False)
        return p

    def _solve_reduced_system(system, gens, entry=False):
        if len(system) == len(gens) == 1:
            zeros = list(roots(system[0], gens[-1], strict=strict).keys())
            return [(zero,) for zero in zeros]
        basis = groebner(system, gens, polys=True)
        if len(basis) == 1 and basis[0].is_ground:
            if not entry:
                return []
            else:
                return None
        univariate = list(filter(_is_univariate, basis))
        if len(basis) < len(gens):
            raise NotImplementedError(filldedent('\n                only zero-dimensional systems supported\n                (finite number of solutions)\n                '))
        if len(univariate) == 1:
            f = univariate.pop()
        else:
            raise NotImplementedError(filldedent('\n                only zero-dimensional systems supported\n                (finite number of solutions)\n                '))
        gens = f.gens
        gen = gens[-1]
        zeros = list(roots(f.ltrim(gen), strict=strict).keys())
        if not zeros:
            return []
        if len(basis) == 1:
            return [(zero,) for zero in zeros]
        solutions = []
        for zero in zeros:
            new_system = []
            new_gens = gens[:-1]
            for b in basis[:-1]:
                eq = _subs_root(b, gen, zero)
                if eq is not S.Zero:
                    new_system.append(eq)
            for solution in _solve_reduced_system(new_system, new_gens):
                solutions.append(solution + (zero,))
        if solutions and len(solutions[0]) != len(gens):
            raise NotImplementedError(filldedent('\n                only zero-dimensional systems supported\n                (finite number of solutions)\n                '))
        return solutions
    try:
        result = _solve_reduced_system(polys, opt.gens, entry=True)
    except CoercionFailed:
        raise NotImplementedError
    if result is not None:
        return sorted(result, key=default_sort_key)

def solve_triangulated(polys, *gens, **args):
    G = groebner(polys, gens, polys=True)
    G = list(reversed(G))
    domain = args.get('domain')
    if domain is not None:
        for i, g in enumerate(G):
            G[i] = g.set_domain(domain)
    f, G = (G[0].ltrim(-1), G[1:])
    dom = f.get_domain()
    zeros = f.ground_roots()
    solutions = {((zero,), dom) for zero in zeros}
    var_seq = reversed(gens[:-1])
    vars_seq = postfixes(gens[1:])
    for var, vars in zip(var_seq, vars_seq):
        _solutions = set()
        for values, dom in solutions:
            H, mapping = ([], list(zip(vars, values)))
            for g in G:
                _vars = (var,) + vars
                if g.has_only_gens(*_vars) and g.degree(var) != 0:
                    h = g.ltrim(var).eval(dict(mapping))
                    if g.degree(var) == h.degree():
                        H.append(h)
            p = min(H, key=lambda h: h.degree())
            zeros = p.ground_roots()
            for zero in zeros:
                if not zero.is_Rational:
                    dom_zero = dom.algebraic_field(zero)
                else:
                    dom_zero = dom
                _solutions.add(((zero,) + values, dom_zero))
        solutions = _solutions
    solutions = list(solutions)
    for i, (solution, _) in enumerate(solutions):
        solutions[i] = solution
    return sorted(solutions, key=default_sort_key)

