def recast_to_symbols(eqs, symbols):
    if not iterable(eqs) and iterable(symbols):
        raise ValueError('Both eqs and symbols must be iterable')
    orig = list(symbols)
    symbols = list(ordered(symbols))
    swap_sym = {}
    i = 0
    for s in symbols:
        if not isinstance(s, Symbol) and s not in swap_sym:
            swap_sym[s] = Dummy('X%d' % i)
            i += 1
    new_f = []
    for i in eqs:
        isubs = getattr(i, 'subs', None)
        if isubs is not None:
            new_f.append(isubs(swap_sym))
        else:
            new_f.append(i)
    restore = {v: k for k, v in swap_sym.items()}
    return (new_f, [swap_sym.get(i, i) for i in orig], restore)

def _ispow(e):
    return isinstance(e, Expr) and (e.is_Pow or isinstance(e, exp))

def _simple_dens(f, symbols):
    dens = set()
    for d in denoms(f, symbols):
        if d.is_Pow and d.exp.is_Number:
            if d.exp.is_zero:
                continue
            d = d.base
        dens.add(d)
    return dens

def denoms(eq, *symbols):
    pot = preorder_traversal(eq)
    dens = set()
    for p in pot:
        if not isinstance(p, Expr):
            continue
        den = denom(p)
        if den is S.One:
            continue
        dens.update(Mul.make_args(den))
    if not symbols:
        return dens
    elif len(symbols) == 1:
        if iterable(symbols[0]):
            symbols = symbols[0]
    return {d for d in dens if any((s in d.free_symbols for s in symbols))}

def checksol(f, symbol, sol=None, **flags):
    from sympy.physics.units import Unit
    minimal = flags.get('minimal', False)
    if sol is not None:
        sol = {symbol: sol}
    elif isinstance(symbol, dict):
        sol = symbol
    else:
        msg = 'Expecting (sym, val) or ({sym: val}, None) but got (%s, %s)'
        raise ValueError(msg % (symbol, sol))
    if iterable(f):
        if not f:
            raise ValueError('no functions to check')
        rv = True
        for fi in f:
            check = checksol(fi, sol, **flags)
            if check:
                continue
            if check is False:
                return False
            rv = None
        return rv
    f = _sympify(f)
    if f.is_number:
        return f.is_zero
    if isinstance(f, Poly):
        f = f.as_expr()
    elif isinstance(f, (Eq, Ne)):
        if f.rhs in (S.true, S.false):
            f = f.reversed
        B, E = f.args
        if isinstance(B, BooleanAtom):
            f = f.subs(sol)
            if not f.is_Boolean:
                return
        elif isinstance(f, Eq):
            f = Add(f.lhs, -f.rhs, evaluate=False)
    if isinstance(f, BooleanAtom):
        return bool(f)
    elif not f.is_Relational and (not f):
        return True
    illegal = set(_illegal)
    if any((sympify(v).atoms() & illegal for k, v in sol.items())):
        return False
    attempt = -1
    numerical = flags.get('numerical', True)
    while 1:
        attempt += 1
        if attempt == 0:
            val = f.subs(sol)
            if isinstance(val, Mul):
                val = val.as_independent(Unit)[0]
            if val.atoms() & illegal:
                return False
        elif attempt == 1:
            if not val.is_number:
                if not val.is_constant(*list(sol.keys()), simplify=not minimal):
                    return False
                _, val = val.as_content_primitive()
                val = _mexpand(val.as_numer_denom()[0], recursive=True)
        elif attempt == 2:
            if minimal:
                return
            if flags.get('simplify', True):
                for k in sol:
                    sol[k] = simplify(sol[k])
            val = simplify(f.subs(sol))
            if flags.get('force', True):
                val, reps = posify(val)
                exval = _mexpand(val, recursive=True)
                if exval.is_number:
                    val = exval
        else:
            pot = preorder_traversal(expand_mul(val))
            seen = set()
            saw_pow_func = False
            for p in pot:
                if p in seen:
                    continue
                seen.add(p)
                if p.is_Pow and (not p.exp.is_Integer):
                    saw_pow_func = True
                elif p.is_Function:
                    saw_pow_func = True
                elif isinstance(p, UndefinedFunction):
                    saw_pow_func = True
                if saw_pow_func:
                    break
            if saw_pow_func is False:
                return False
            if flags.get('force', True):
                val = val.subs(reps)
            nz = fuzzy_not(val.is_zero)
            if nz is not None:
                if val.is_number and val.has(LambertW):
                    return None
                return not nz
            break
        if val.is_Rational:
            return val == 0
        if numerical and val.is_number:
            return (abs(val.n(18).n(12, chop=True)) < 1e-09) is S.true
    if flags.get('warn', False):
        warnings.warn('\n\tWarning: could not verify solution %s.' % sol)

def solve(f, *symbols, **flags):
    from .inequalities import reduce_inequalities
    hints = ('cubics', 'quartics', 'quintics')
    default = True
    for k in hints:
        default = flags.setdefault(k, bool(flags.get(k, default)))
    implicit = flags.get('implicit', False)
    warn = flags.get('warn', False)
    as_set = flags.get('set', False)
    bare_f = not iterable(f)
    if flags.get('quick', None) is not None:
        if not flags.get('particular', None):
            raise ValueError('when using `quick`, `particular` should be True')
    if flags.get('particular', False) and bare_f:
        raise ValueError(filldedent("\n            The 'particular/quick' flag is usually used with systems of\n            equations. Either pass your equation in a list or\n            consider using a solver like `diophantine` if you are\n            looking for a solution in integers."))

    def _sympified_list(w):
        return list(map(sympify, w if iterable(w) else [w]))
    f, symbols = (_sympified_list(w) for w in [f, symbols])
    ordered_symbols = None
    if not symbols:
        symbols = set().union(*[fi.free_symbols for fi in f])
        if len(symbols) < len(f):
            for fi in f:
                pot = preorder_traversal(fi)
                for p in pot:
                    if isinstance(p, AppliedUndef):
                        if not as_set:
                            flags['dict'] = True
                        symbols.add(p)
                        pot.skip()
        ordered_symbols = False
        symbols = list(ordered(symbols))
    else:
        if len(symbols) == 1 and iterable(symbols[0]):
            symbols = symbols[0]
        ordered_symbols = symbols and is_sequence(symbols, include=GeneratorType)
        _symbols = list(uniq(symbols))
        if len(_symbols) != len(symbols):
            ordered_symbols = False
            symbols = list(ordered(symbols))
        else:
            symbols = _symbols
    if len(symbols) != len(set(symbols)):
        raise ValueError('duplicate symbols given')
    exclude = flags.pop('exclude', set())
    if exclude:
        if isinstance(exclude, Expr):
            exclude = [exclude]
        exclude = set().union(*[e.free_symbols for e in sympify(exclude)])
        symbols = [s for s in symbols if s not in exclude]
    if isinstance(f, list):
        f = [s for s in f if s is not S.true]
    for i, fi in enumerate(f):
        if isinstance(fi, (Eq, Ne)):
            if 'ImmutableDenseMatrix' in [type(a).__name__ for a in fi.args]:
                fi = fi.lhs - fi.rhs
            else:
                L, R = fi.args
                if isinstance(R, BooleanAtom):
                    L, R = (R, L)
                if isinstance(L, BooleanAtom):
                    if isinstance(fi, Ne):
                        L = ~L
                    if R.is_Relational:
                        fi = ~R if L is S.false else R
                    elif R.is_Symbol:
                        return L
                    elif R.is_Boolean and (~R).is_Symbol:
                        return ~L
                    else:
                        raise NotImplementedError(filldedent('\n                            Unanticipated argument of Eq when other arg\n                            is True or False.\n                        '))
                elif isinstance(fi, Eq):
                    fi = Add(fi.lhs, -fi.rhs, evaluate=False)
            f[i] = fi
        if fi.is_Relational:
            if len(symbols) != 1:
                raise ValueError('can only solve for one symbol at a time')
            if warn and symbols[0].assumptions0:
                warnings.warn(filldedent("\n                    \tWarning: assumptions about variable '%s' are\n                    not handled currently." % symbols[0]))
            return reduce_inequalities(f, symbols=symbols)
        if isinstance(fi, Poly):
            f[i] = fi.as_expr()
        f[i] = f[i].replace(lambda w: isinstance(w, HyperbolicFunction) and w.has_free(*symbols), lambda w: w.rewrite(exp))
        if f[i].is_Matrix:
            bare_f = False
            f.extend(list(f[i]))
            f[i] = S.Zero
        freei = f[i].free_symbols
        if freei and all((s.is_extended_real or s.is_imaginary for s in freei)):
            fr, fi = f[i].as_real_imag()
            had = f[i].atoms(re, im, arg, atan2)
            if fr and fi and (fr != fi) and (not any((i.atoms(re, im, arg, atan2) - had for i in (fr, fi)))):
                if bare_f:
                    bare_f = False
                f[i:i + 1] = [fr, fi]
    if any((isinstance(fi, (bool, BooleanAtom)) for fi in f)):
        if as_set:
            return ([], set())
        return []
    for i, fi in enumerate(f):
        while True:
            was = fi
            fi = fi.replace(Abs, lambda arg: separatevars(Abs(arg)).rewrite(Piecewise) if arg.has(*symbols) else Abs(arg))
            if was == fi:
                break
        for e in fi.find(Abs):
            if e.has(*symbols):
                raise NotImplementedError('solving %s when the argument is not real or imaginary.' % e)
        fi = fi.replace(arg, lambda a: arg(a).rewrite(atan2).rewrite(atan))
        f[i] = fi
    freim = [fi for fi in f if fi.has(re, im)]
    if freim:
        irf = []
        for s in symbols:
            if s.is_real or s.is_imaginary:
                continue
            if any((fi.has(re(s), im(s)) for fi in freim)):
                irf.append((s, re(s) + S.ImaginaryUnit * im(s)))
        if irf:
            for s, rhs in irf:
                f = [fi.xreplace({s: rhs}) for fi in f] + [s - rhs]
                symbols.extend([re(s), im(s)])
            if bare_f:
                bare_f = False
            flags['dict'] = True
    f, symbols, swap_sym = recast_to_symbols(f, symbols)
    symset = set(symbols)
    newf = []
    for fi in f:
        ok = False
        if fi.free_symbols & symset:
            ok = True
        elif fi.is_number:
            if fi.is_Number:
                if fi.is_zero:
                    continue
                return []
            ok = True
        elif fi.is_constant():
            ok = True
        if ok:
            newf.append(fi)
    if not newf:
        if as_set:
            return (symbols, set())
        return []
    f = newf
    del newf
    seen = set()
    non_inverts = set()
    for fi in f:
        pot = preorder_traversal(fi)
        for p in pot:
            if not isinstance(p, Expr) or isinstance(p, Piecewise):
                pass
            elif (isinstance(p, bool) or not p.args or p in symset or p.is_Add or p.is_Mul or (p.is_Pow and (not implicit)) or (p.is_Function and (not implicit))) and p.func not in (re, im):
                continue
            elif p not in seen:
                seen.add(p)
                if p.free_symbols & symset:
                    non_inverts.add(p)
                else:
                    continue
            pot.skip()
    del seen
    non_inverts = dict(list(zip(non_inverts, [Dummy() for _ in non_inverts])))
    f = [fi.subs(non_inverts) for fi in f]
    non_inverts = [(v, k.xreplace(swap_sym).subs(swap_sym)) for k, v in non_inverts.items()]
    floats = False
    if flags.get('rational', True) is not False:
        for i, fi in enumerate(f):
            if fi.has(Float):
                floats = True
                f[i] = nsimplify(fi, rational=True)
    flags['_denominators'] = _simple_dens(f[0], symbols)

    def _has_piecewise(e):
        if e.is_Piecewise:
            return e.has(*symbols)
        return any((_has_piecewise(a) for a in e.args))
    for i, fi in enumerate(f):
        if _has_piecewise(fi):
            f[i] = piecewise_fold(fi)
    targs = {t for fi in f for t in fi.atoms(TrigonometricFunction)}
    if len(targs) > 1:
        add, other = sift(targs, lambda x: x.args[0].is_Add, binary=True)
        add, other = [[i for i in l if i.has_free(*symbols)] for l in (add, other)]
        trep = {}
        for t in add:
            a = t.args[0]
            ind, dep = a.as_independent(*symbols)
            if dep in symbols or -dep in symbols:
                n = Dummy() if not ind.is_Number else ind
                trep[t] = TR10(t.func(dep + n)).xreplace({n: ind})
        if other and len(other) <= 2:
            base = gcd(*[i.args[0] for i in other]) if len(other) > 1 else other[0].args[0]
            for i in other:
                trep[i] = TR11(i, base)
        f = [fi.xreplace(trep) for fi in f]
    if bare_f:
        solution = None
        if len(symbols) != 1:
            solution = _solve_undetermined(f[0], symbols, flags)
        if not solution:
            solution = _solve(f[0], *symbols, **flags)
    else:
        linear, solution = _solve_system(f, symbols, **flags)
    assert type(solution) is list
    assert not solution or type(solution[0]) is dict, solution
    as_dict = flags.get('dict', False)
    tuple_format = lambda s: [tuple([i.get(x, x) for x in symbols]) for i in s]
    if as_dict or as_set:
        unpack = None
    elif bare_f:
        if len(symbols) == 1:
            unpack = lambda s: [i[symbols[0]] for i in s]
        elif len(solution) == 1 and len(solution[0]) == len(symbols):
            unpack = lambda s: s[0]
        elif ordered_symbols:
            unpack = tuple_format
        else:
            unpack = lambda s: s
    elif solution:
        if linear and len(solution) == 1:
            unpack = lambda s: s[0]
        elif ordered_symbols:
            unpack = tuple_format
        else:
            unpack = lambda s: s
    else:
        unpack = None
    if non_inverts and type(solution) is list:
        solution = [{k: v.subs(non_inverts) for k, v in s.items()} for s in solution]
    if swap_sym:
        symbols = [swap_sym.get(k, k) for k in symbols]
        for i, sol in enumerate(solution):
            solution[i] = {swap_sym.get(k, k): v.subs(swap_sym) for k, v in sol.items()}
    check = flags.get('check', True)
    if floats and solution and (flags.get('rational', None) is None):
        solution = nfloat(solution, exponent=False)
        solution = _remove_duplicate_solutions(solution)
    if check and solution:
        warn = flags.get('warn', False)
        got_None = []
        no_False = []
        for sol in solution:
            a_None = False
            for symb, val in sol.items():
                test = check_assumptions(val, **symb.assumptions0)
                if test:
                    continue
                if test is False:
                    break
                a_None = True
            else:
                no_False.append(sol)
                if a_None:
                    got_None.append(sol)
        solution = no_False
        if warn and got_None:
            warnings.warn(filldedent('\n                \tWarning: assumptions concerning following solution(s)\n                cannot be checked:' + '\n\t' + ', '.join((str(s) for s in got_None))))
    if not solution:
        if as_set:
            return (symbols, set())
        return []
    if not as_set:
        solution = [{k: s[k] for k in ordered(s)} for s in solution]
        solution.sort(key=default_sort_key)
    if not (as_set or as_dict):
        return unpack(solution)
    if as_dict:
        return solution
    if ordered_symbols:
        k = symbols
    else:
        k = list(ordered(set(flatten((tuple(i.keys()) for i in solution)))))
    return (k, {tuple([s.get(ki, ki) for ki in k]) for s in solution})

def _solve_undetermined(g, symbols, flags):
    if g.free_symbols - set(symbols):
        sol = solve_undetermined_coeffs(g, symbols, **dict(flags, dict=True, set=None))
        if len(sol) == 1:
            return sol

def _solve(f, *symbols, **flags):
    not_impl_msg = 'No algorithms are implemented to solve equation %s'
    if len(symbols) != 1:
        nonlin_s = []
        got_s = set()
        rhs_s = set()
        result = []
        for s in symbols:
            xi, v = solve_linear(f, symbols=[s])
            if xi == s:
                if flags.get('simplify', True):
                    v = simplify(v)
                vfree = v.free_symbols
                if vfree & got_s:
                    continue
                rhs_s |= vfree
                got_s.add(xi)
                result.append({xi: v})
            elif xi:
                nonlin_s.append(s)
        if not nonlin_s:
            return result
        for s in nonlin_s:
            try:
                soln = _solve(f, s, **flags)
                for sol in soln:
                    if sol[s].free_symbols & got_s:
                        continue
                    got_s.add(s)
                    result.append(sol)
            except NotImplementedError:
                continue
        if got_s:
            return result
        else:
            raise NotImplementedError(not_impl_msg % f)
    symbol = symbols[0]
    f = f.replace(lambda e: isinstance(e, binomial) and e.has(symbol), lambda e: expand_func(e))
    flags['check'] = checkdens = check = flags.pop('check', True)
    if f.is_Mul:
        result = set()
        for m in f.args:
            if m in {S.NegativeInfinity, S.ComplexInfinity, S.Infinity}:
                result = set()
                break
            soln = _vsolve(m, symbol, **flags)
            result.update(set(soln))
        result = [{symbol: v} for v in result]
        if check:
            dens = flags.get('_denominators', _simple_dens(f, symbols))
            result = [s for s in result if not any((checksol(den, s, **flags) for den in dens))]
        check = False
        flags['simplify'] = False
    elif f.is_Piecewise:
        result = set()
        if any((e.is_zero for e, c in f.args)):
            f = f.simplify()
        cond = neg = True
        for expr, cnd in f.args:
            cond = And(neg, cnd)
            neg = And(neg, ~cond)
            if expr.is_zero and cond.simplify() != False:
                raise NotImplementedError(filldedent('\n                    An expression is already zero when %s.\n                    This means that in this *region* the solution\n                    is zero but solve can only represent discrete,\n                    not interval, solutions. If this is a spurious\n                    interval it might be resolved with simplification\n                    of the Piecewise conditions.' % cond))
            candidates = _vsolve(expr, symbol, **flags)
            for candidate in candidates:
                if candidate in result:
                    continue
                try:
                    v = cond.subs(symbol, candidate)
                    _eval_simplify = getattr(v, '_eval_simplify', None)
                    if _eval_simplify is not None:
                        v = _eval_simplify(ratio=2, measure=lambda x: 1)
                except TypeError:
                    continue
                if v == False:
                    continue
                if v == True:
                    result.add(candidate)
                else:
                    result.add(Piecewise((candidate, v), (S.NaN, True)))
        return [{symbol: r} for r in result]
    else:
        f_num, sol = solve_linear(f, symbols=symbols)
        if f_num.is_zero or sol is S.NaN:
            return []
        elif f_num.is_Symbol:
            if flags.get('simplify', True):
                sol = simplify(sol)
            return [{f_num: sol}]
        poly = None
        if not f_num.is_Add:
            add_args = [i for i in f_num.atoms(Add) if symbol in i.free_symbols]
            if len(add_args) == 1:
                gen = add_args[0]
                spart = gen.as_independent(symbol)[1].as_base_exp()[0]
                if spart == symbol:
                    try:
                        poly = Poly(f_num, spart)
                    except PolynomialError:
                        pass
        result = False
        msg = ''
        try:
            if poly is None:
                poly = Poly(f_num)
            if poly is None:
                raise ValueError('could not convert %s to Poly' % f_num)
        except GeneratorsNeeded:
            simplified_f = simplify(f_num)
            if simplified_f != f_num:
                return _solve(simplified_f, symbol, **flags)
            raise ValueError('expression appears to be a constant')
        gens = [g for g in poly.gens if g.has(symbol)]

        def _as_base_q(x):
            b, e = x.as_base_exp()
            if e.is_Rational:
                return (b, e.q)
            if not e.is_Mul:
                return (x, 1)
            c, ee = e.as_coeff_Mul()
            if c.is_Rational and c is not S.One:
                return (b ** ee, c.q)
            return (x, 1)
        if len(gens) > 1:
            bases, qs = list(zip(*[_as_base_q(g) for g in gens]))
            bases = set(bases)
            if len(bases) > 1 or not all((q == 1 for q in qs)):
                funcs = {b for b in bases if b.is_Function}
                trig = {_ for _ in funcs if isinstance(_, TrigonometricFunction)}
                other = funcs - trig
                if not other and len(funcs.intersection(trig)) > 1:
                    newf = None
                    if f_num.is_Add and len(f_num.args) == 2:
                        _args = f_num.args
                        t = a, b = [i.atoms(Function).intersection(trig) for i in _args]
                        if all((len(i) == 1 for i in t)):
                            a, b = [i.pop() for i in t]
                            if isinstance(a, cos):
                                a, b = (b, a)
                                _args = _args[::-1]
                            if isinstance(a, sin) and isinstance(b, cos) and (a.args[0] == b.args[0]):
                                newf, _d = (TR2i(_args[0] / _args[1]) + 1).as_numer_denom()
                                if not _d.is_Number:
                                    newf = None
                    if newf is None:
                        newf = TR1(f_num).rewrite(tan)
                    if newf != f_num:
                        flags['check'] = False
                        result = _solve(newf, symbol, **flags)
                        flags['check'] = check
                if result is False and funcs:
                    funcs = list(ordered(funcs))
                    f1 = funcs[0]
                    t = Dummy('t')
                    ftry = f_num.subs(f1, t)
                    if not ftry.has(symbol):
                        cv_sols = _solve(ftry, t, **flags)
                        cv_inv = list(ordered(_vsolve(t - f1, symbol, **flags)))[0]
                        result = [{symbol: cv_inv.subs(sol)} for sol in cv_sols]
                if result is False:
                    msg = 'multiple generators %s' % gens
            else:
                u = bases.pop()
                t = Dummy('t')
                inv = _vsolve(u - t, symbol, **flags)
                if isinstance(u, (Pow, exp)):

                    def _expand(p):
                        b, e = p.as_base_exp()
                        e = expand_mul(e)
                        return expand_power_exp(b ** e)
                    ftry = f_num.replace(lambda w: w.is_Pow or isinstance(w, exp), _expand).subs(u, t)
                    if not ftry.has(symbol):
                        soln = _solve(ftry, t, **flags)
                        result = [{symbol: i.subs(s)} for i in inv for s in soln]
        elif len(gens) == 1:
            poly = Poly(f_num, gens[0], composite=True)
            if not flags.pop('tsolve', False):
                soln = None
                deg = poly.degree()
                flags['tsolve'] = True
                hints = ('cubics', 'quartics', 'quintics')
                solvers = {h: flags.get(h) for h in hints}
                soln = roots(poly, **solvers)
                if sum(soln.values()) < deg:
                    try:
                        soln = poly.all_roots()
                    except NotImplementedError:
                        if not flags.get('incomplete', True):
                            raise NotImplementedError(filldedent('\n    Neither high-order multivariate polynomials\n    nor sorting of EX-domain polynomials is supported.\n    If you want to see any results, pass keyword incomplete=True to\n    solve; to see numerical values of roots\n    for univariate expressions, use nroots.\n    '))
                        else:
                            pass
                else:
                    soln = list(soln.keys())
                if soln is not None:
                    u = poly.gen
                    if u != symbol:
                        try:
                            t = Dummy('t')
                            inv = _vsolve(u - t, symbol, **flags)
                            soln = {i.subs(t, s) for i in inv for s in soln}
                        except NotImplementedError:
                            soln = None
                    else:
                        check = False
                    if soln is not None:
                        if len(soln) > 2:
                            flags['simplify'] = flags.get('simplify', False)
                if soln is not None:
                    result = [{symbol: v} for v in soln]
    if result is False:
        if flags.pop('_unrad', True):
            try:
                u = unrad(f_num, symbol)
            except (ValueError, NotImplementedError):
                u = False
            if u:
                eq, cov = u
                if cov:
                    isym, ieq = cov
                    inv = _vsolve(ieq, symbol, **flags)[0]
                    rv = {inv.subs(xi) for xi in _solve(eq, isym, **flags)}
                else:
                    try:
                        rv = set(_vsolve(eq, symbol, **flags))
                    except NotImplementedError:
                        rv = None
                if rv is not None:
                    result = [{symbol: v} for v in rv]
                    flags['simplify'] = flags.get('simplify', False)
            else:
                pass
    if result is False:
        flags.pop('tsolve', None)
        try:
            soln = _tsolve(f_num, symbol, **flags)
            if soln is not None:
                result = [{symbol: v} for v in soln]
        except PolynomialError:
            pass
    if result is False:
        raise NotImplementedError('\n'.join([msg, not_impl_msg % f]))
    result = _remove_duplicate_solutions(result)
    if flags.get('simplify', True):
        result = [{k: d[k].simplify() for k in d} for d in result]
        result = _remove_duplicate_solutions(result)
        flags['simplify'] = False
    if checkdens:
        dens = _simple_dens(f, symbols)
        result = [r for r in result if not any((checksol(d, r, **flags) for d in dens))]
    if check:
        result = [r for r in result if checksol(f_num, r, **flags) is not False]
    return result

def _remove_duplicate_solutions(solutions: list[dict[Expr, Expr]]) -> list[dict[Expr, Expr]]:
    solutions_set = set()
    solutions_new = []
    for sol in solutions:
        solset = frozenset(sol.items())
        if solset not in solutions_set:
            solutions_new.append(sol)
            solutions_set.add(solset)
    return solutions_new

def _solve_system(exprs, symbols, **flags):
    if not exprs:
        return (False, [])
    if flags.pop('_split', True):
        V = exprs
        symsset = set(symbols)
        exprsyms = {e: e.free_symbols & symsset for e in exprs}
        E = []
        sym_indices = {sym: i for i, sym in enumerate(symbols)}
        for n, e1 in enumerate(exprs):
            for e2 in exprs[:n]:
                if exprsyms[e1] & exprsyms[e2]:
                    E.append((e1, e2))
        G = (V, E)
        subexprs = connected_components(G)
        if len(subexprs) > 1:
            subsols = []
            linear = True
            for subexpr in subexprs:
                subsyms = set()
                for e in subexpr:
                    subsyms |= exprsyms[e]
                subsyms = sorted(subsyms, key=lambda x: sym_indices[x])
                flags['_split'] = False
                _linear, subsol = _solve_system(subexpr, subsyms, **flags)
                if linear:
                    linear = linear and _linear
                if not isinstance(subsol, list):
                    subsol = [subsol]
                subsols.append(subsol)
            sols = []
            for soldicts in product(*subsols):
                sols.append(dict((item for sd in soldicts for item in sd.items())))
            return (linear, sols)
    polys = []
    dens = set()
    failed = []
    result = []
    solved_syms = []
    linear = True
    manual = flags.get('manual', False)
    checkdens = check = flags.get('check', True)
    for j, g in enumerate(exprs):
        dens.update(_simple_dens(g, symbols))
        i, d = _invert(g, *symbols)
        if d in symbols:
            if linear:
                linear = solve_linear(g, 0, [d])[0] == d
        g = d - i
        g = g.as_numer_denom()[0]
        if manual:
            failed.append(g)
            continue
        poly = g.as_poly(*symbols, extension=True)
        if poly is not None:
            polys.append(poly)
        else:
            failed.append(g)
    if polys:
        if all((p.is_linear for p in polys)):
            n, m = (len(polys), len(symbols))
            matrix = zeros(n, m + 1)
            for i, poly in enumerate(polys):
                for monom, coeff in poly.terms():
                    try:
                        j = monom.index(1)
                        matrix[i, j] = coeff
                    except ValueError:
                        matrix[i, m] = -coeff
            if flags.pop('particular', False):
                result = minsolve_linear_system(matrix, *symbols, **flags)
            else:
                result = solve_linear_system(matrix, *symbols, **flags)
            result = [result] if result else []
            if failed:
                if result:
                    solved_syms = list(result[0].keys())
                else:
                    solved_syms = []
        else:
            linear = False
            if len(symbols) > len(polys):
                free = set().union(*[p.free_symbols for p in polys])
                free = list(ordered(free.intersection(symbols)))
                got_s = set()
                result = []
                for syms in subsets(free, len(polys)):
                    try:
                        res = solve_poly_system(polys, *syms)
                        if res:
                            for r in set(res):
                                skip = False
                                for r1 in r:
                                    if got_s and any((ss in r1.free_symbols for ss in got_s)):
                                        skip = True
                                if not skip:
                                    got_s.update(syms)
                                    result.append(dict(list(zip(syms, r))))
                    except NotImplementedError:
                        pass
                if got_s:
                    solved_syms = list(got_s)
                else:
                    raise NotImplementedError('no valid subset found')
            else:
                try:
                    result = solve_poly_system(polys, *symbols)
                    if result:
                        solved_syms = symbols
                        result = [dict(list(zip(solved_syms, r))) for r in set(result)]
                except NotImplementedError:
                    failed.extend([g.as_expr() for g in polys])
                    solved_syms = []
    result = result or [{}]
    if failed:
        linear = False

        def _ok_syms(e, sort=False):
            rv = e.free_symbols & legal

            def key(sym):
                ep = e.as_poly(sym)
                if ep is None:
                    complexity = (S.Infinity, S.Infinity, S.Infinity)
                else:
                    coeff_syms = ep.LC().free_symbols
                    complexity = (ep.degree(), len(coeff_syms & rv), len(coeff_syms))
                return complexity + (default_sort_key(sym),)
            if sort:
                rv = sorted(rv, key=key)
            return rv
        legal = set(symbols)
        u = Dummy()
        for eq in ordered(failed, lambda _: len(_ok_syms(_))):
            newresult = []
            bad_results = []
            hit = False
            for r in result:
                got_s = set()
                eq2 = eq.subs(r)
                if check and r:
                    b = checksol(u, u, eq2, minimal=True)
                    if b is not None:
                        if b:
                            newresult.append(r)
                        else:
                            bad_results.append(r)
                        continue
                ok_syms = _ok_syms(eq2, sort=True)
                if not ok_syms:
                    if r:
                        newresult.append(r)
                    break
                for s in ok_syms:
                    try:
                        soln = _vsolve(eq2, s, **flags)
                    except NotImplementedError:
                        continue
                    for sol in soln:
                        if got_s and any((ss in sol.free_symbols for ss in got_s)):
                            continue
                        rnew = r.copy()
                        for k, v in r.items():
                            rnew[k] = v.subs(s, sol)
                        rnew[s] = sol
                        iset = set(rnew.items())
                        for i in newresult:
                            if len(i) < len(iset) and (not set(i.items()) - iset):
                                break
                        else:
                            newresult.append(rnew)
                    hit = True
                    got_s.add(s)
                if not hit:
                    raise NotImplementedError('could not solve %s' % eq2)
            else:
                result = newresult
                for b in bad_results:
                    if b in result:
                        result.remove(b)
    if not result:
        return (False, [])
    default_simplify = bool(failed)
    if flags.get('simplify', default_simplify):
        for r in result:
            for k in r:
                r[k] = simplify(r[k])
        flags['simplify'] = False
    if checkdens:
        result = [r for r in result if not any((checksol(d, r, **flags) for d in dens))]
    if check and (not linear):
        result = [r for r in result if not any((checksol(e, r, **flags) is False for e in exprs))]
    result = [r for r in result if r]
    return (linear, result)

def solve_linear(lhs, rhs=0, symbols=[], exclude=[]):
    if isinstance(lhs, Eq):
        if rhs:
            raise ValueError(filldedent('\n            If lhs is an Equality, rhs must be 0 but was %s' % rhs))
        rhs = lhs.rhs
        lhs = lhs.lhs
    dens = None
    eq = lhs - rhs
    n, d = eq.as_numer_denom()
    if not n:
        return (S.Zero, S.One)
    free = n.free_symbols
    if not symbols:
        symbols = free
    else:
        bad = [s for s in symbols if not s.is_Symbol]
        if bad:
            if len(bad) == 1:
                bad = bad[0]
            if len(symbols) == 1:
                eg = 'solve(%s, %s)' % (eq, symbols[0])
            else:
                eg = 'solve(%s, *%s)' % (eq, list(symbols))
            raise ValueError(filldedent('\n                solve_linear only handles symbols, not %s. To isolate\n                non-symbols use solve, e.g. >>> %s <<<.\n                             ' % (bad, eg)))
        symbols = free.intersection(symbols)
    symbols = symbols.difference(exclude)
    if not symbols:
        return (S.Zero, S.One)
    derivs = defaultdict(list)
    for der in n.atoms(Derivative):
        csym = der.free_symbols & symbols
        for c in csym:
            derivs[c].append(der)
    all_zero = True
    for xi in sorted(symbols, key=default_sort_key):
        if isinstance(derivs[xi], list):
            derivs[xi] = {der: der.doit() for der in derivs[xi]}
        newn = n.subs(derivs[xi])
        dnewn_dxi = newn.diff(xi)
        free = dnewn_dxi.free_symbols
        if dnewn_dxi and (not free or any((dnewn_dxi.diff(s) for s in free)) or free == symbols):
            all_zero = False
            if dnewn_dxi is S.NaN:
                break
            if xi not in dnewn_dxi.free_symbols:
                vi = -1 / dnewn_dxi * newn.subs(xi, 0)
                if dens is None:
                    dens = _simple_dens(eq, symbols)
                if not any((checksol(di, {xi: vi}, minimal=True) is True for di in dens)):
                    irep = [(i, i.doit()) for i in vi.atoms(Integral) if i.function.is_number]
                    vi = expand_mul(vi.subs(irep))
                    return (xi, vi)
    if all_zero:
        return (S.Zero, S.One)
    if n.is_Symbol:
        return (S.Zero, S.Zero)
    return (n, d)

def minsolve_linear_system(system, *symbols, **flags):
    quick = flags.get('quick', False)
    s0 = solve_linear_system(system, *symbols, **flags)
    if not s0 or all((v == 0 for v in s0.values())):
        return s0
    if quick:
        s = solve_linear_system(system, *symbols)

        def update(determined, solution):
            delete = []
            for k, v in solution.items():
                solution[k] = v.subs(determined)
                if not solution[k].free_symbols:
                    delete.append(k)
                    determined[k] = solution[k]
            for k in delete:
                del solution[k]
        determined = {}
        update(determined, s)
        while s:
            k = max((k for k in s.values()), key=lambda x: (len(x.free_symbols), default_sort_key(x)))
            kfree = k.free_symbols
            x = next(reversed(list(ordered(kfree))))
            if len(kfree) != 1:
                determined[x] = S.Zero
            else:
                val = _vsolve(k, x, check=False)[0]
                if not val and (not any((v.subs(x, val) for v in s.values()))):
                    determined[x] = S.One
                else:
                    determined[x] = val
            update(determined, s)
        return determined
    else:
        N = len(symbols)
        bestsol = minsolve_linear_system(system, *symbols, quick=True)
        n0 = len([x for x in bestsol.values() if x != 0])
        for n in range(n0 - 1, 1, -1):
            debugf('minsolve: %s', n)
            thissol = None
            for nonzeros in combinations(range(N), n):
                subm = Matrix([system.col(i).T for i in nonzeros] + [system.col(-1).T]).T
                s = solve_linear_system(subm, *[symbols[i] for i in nonzeros])
                if s and (not all((v == 0 for v in s.values()))):
                    subs = [(symbols[v], S.One) for v in nonzeros]
                    for k, v in s.items():
                        s[k] = v.subs(subs)
                    for sym in symbols:
                        if sym not in s:
                            if symbols.index(sym) in nonzeros:
                                s[sym] = S.One
                            else:
                                s[sym] = S.Zero
                    thissol = s
                    break
            if thissol is None:
                break
            bestsol = thissol
        return bestsol

def solve_linear_system(system, *symbols, **flags):
    assert system.shape[1] == len(symbols) + 1
    eqs = list(system * Matrix(symbols + (-1,)))
    eqs, ring = sympy_eqs_to_ring(eqs, symbols)
    sol = solve_lin_sys(eqs, ring, _raw=False)
    if sol is not None:
        sol = {sym: val for sym, val in sol.items() if sym != val}
    return sol

def solve_undetermined_coeffs(equ, coeffs, *syms, **flags):
    if not (coeffs and all((i.is_Symbol for i in coeffs))):
        raise ValueError('must provide symbols for coeffs')
    if isinstance(equ, Eq):
        eq = equ.lhs - equ.rhs
    else:
        eq = equ
    ceq = cancel(eq)
    xeq = _mexpand(ceq.as_numer_denom()[0], recursive=True)
    free = xeq.free_symbols
    coeffs = free & set(coeffs)
    if not coeffs:
        return ([], {}) if flags.get('set', None) else []
    if not syms:
        ind, dep = xeq.as_independent(*coeffs, as_Add=True)
        dfree = dep.free_symbols
        syms = dfree & ind.free_symbols
        if not syms:
            syms = dfree - set(coeffs)
        if not syms:
            syms = [Dummy()]
    else:
        if len(syms) == 1 and iterable(syms[0]):
            syms = syms[0]
        e, s, _ = recast_to_symbols([xeq], syms)
        xeq = e[0]
        syms = s
    gens = set(xeq.as_coefficients_dict(*syms).keys()) - {1}
    cset = set(coeffs)
    if any((g.has_xfree(cset) for g in gens)):
        return
    e, gens, _ = recast_to_symbols([xeq], list(gens))
    xeq = e[0]
    system = list(collect(xeq, gens, evaluate=False).values())
    soln = solve(system, coeffs, **flags)
    settings = flags.get('dict', None) or flags.get('set', None)
    if type(soln) is dict or settings or len(soln) != 1:
        return soln
    return soln[0]

def solve_linear_system_LU(matrix, syms):
    if matrix.rows != matrix.cols - 1:
        raise ValueError('Rows should be equal to columns - 1')
    A = matrix[:matrix.rows, :matrix.rows]
    b = matrix[:, matrix.cols - 1:]
    soln = A.LUsolve(b)
    solutions = {}
    for i in range(soln.rows):
        solutions[syms[i]] = soln[i, 0]
    return solutions

def det_perm(M):
    args = []
    s = True
    n = M.rows
    list_ = M.flat()
    for perm in generate_bell(n):
        fac = []
        idx = 0
        for j in perm:
            fac.append(list_[idx + j])
            idx += n
        term = Mul(*fac)
        args.append(term if s else -term)
        s = not s
    return Add(*args)

def det_minor(M):
    n = M.rows
    if n == 2:
        return M[0, 0] * M[1, 1] - M[1, 0] * M[0, 1]
    else:
        return sum(((1, -1)[i % 2] * Add(*[M[0, i] * d for d in Add.make_args(det_minor(M.minor_submatrix(0, i)))]) if M[0, i] else S.Zero for i in range(n)))

def det_quick(M, method=None):
    if any((i.has(Symbol) for i in M)):
        if M.rows < 8 and all((i.has(Symbol) for i in M)):
            return det_perm(M)
        return det_minor(M)
    else:
        return M.det(method=method) if method else M.det()

def inv_quick(M):
    if not all((i.is_Number for i in M)):
        if not any((i.is_Number for i in M)):
            det = lambda _: det_perm(_)
        else:
            det = lambda _: det_minor(_)
    else:
        return M.inv()
    n = M.rows
    d = det(M)
    if d == S.Zero:
        raise NonInvertibleMatrixError('Matrix det == 0; not invertible')
    ret = zeros(n)
    s1 = -1
    for i in range(n):
        s = s1 = -s1
        for j in range(n):
            di = det(M.minor_submatrix(i, j))
            ret[j, i] = s * di / d
            s = -s
    return ret
multi_inverses = {sin: lambda x: (asin(x), S.Pi - asin(x)), cos: lambda x: (acos(x), 2 * S.Pi - acos(x))}

def _vsolve(e, s, **flags):
    return [i[s] for i in _solve(e, s, **flags)]

def _tsolve(eq, sym, **flags):
    if 'tsolve_saw' not in flags:
        flags['tsolve_saw'] = []
    if eq in flags['tsolve_saw']:
        return None
    else:
        flags['tsolve_saw'].append(eq)
    rhs, lhs = _invert(eq, sym)
    if lhs == sym:
        return [rhs]
    try:
        if lhs.is_Add:
            f = factor(powdenest(lhs - rhs))
            if f.is_Mul:
                return _vsolve(f, sym, **flags)
            if rhs:
                f = logcombine(lhs, force=flags.get('force', True))
                if f.count(log) != lhs.count(log):
                    if isinstance(f, log):
                        return _vsolve(f.args[0] - exp(rhs), sym, **flags)
                    return _tsolve(f - rhs, sym, **flags)
        elif lhs.is_Pow:
            if lhs.exp.is_Integer:
                if lhs - rhs != eq:
                    return _vsolve(lhs - rhs, sym, **flags)
            if sym not in lhs.exp.free_symbols:
                return _vsolve(lhs.base - rhs ** (1 / lhs.exp), sym, **flags)
            if any((t.is_Dummy for t in rhs.free_symbols)):
                raise NotImplementedError
            if not rhs:
                sol_base = _vsolve(lhs.base, sym, **flags)
                return [s for s in sol_base if lhs.exp.subs(sym, s) != 0]
            if not lhs.base.has(sym):
                if lhs.base == 0:
                    return _vsolve(lhs.exp, sym, **flags) if rhs != 0 else []
                if lhs.base == rhs.as_base_exp()[0]:
                    sol = _vsolve(lhs.exp - rhs.as_base_exp()[1], sym, **flags)
                else:
                    f = exp(log(lhs.base) * lhs.exp) - exp(log(rhs))
                    sol = _vsolve(f, sym, **flags)

                def equal(expr1, expr2):
                    _ = Dummy()
                    eq = checksol(expr1 - _, _, expr2)
                    if eq is None:
                        if nsimplify(expr1) != nsimplify(expr2):
                            return False
                        eq = expr1.equals(expr2)
                    return eq
                e_rat = nsimplify(log(abs(rhs)) / log(abs(lhs.base)))
                e_rat = simplify(posify(e_rat)[0])
                n, d = fraction(e_rat)
                if expand(lhs.base ** n - rhs ** d) == 0:
                    sol = [s for s in sol if not equal(lhs.exp.subs(sym, s), e_rat)]
                    sol.extend(_vsolve(lhs.exp - e_rat, sym, **flags))
                return list(set(sol))
            else:
                sol = []
                logform = lhs.exp * log(lhs.base) - log(rhs)
                if logform != lhs - rhs:
                    try:
                        sol.extend(_vsolve(logform, sym, **flags))
                    except NotImplementedError:
                        pass
                check = []
                if rhs == 1:
                    check.extend(_vsolve(lhs.exp, sym, **flags))
                    check.extend(_vsolve(lhs.base - 1, sym, **flags))
                    check.extend(_vsolve(lhs.base + 1, sym, **flags))
                elif rhs.is_Rational:
                    for d in (i for i in divisors(abs(rhs.p)) if i != 1):
                        e, t = integer_log(rhs.p, d)
                        if not t:
                            continue
                        for s in divisors(abs(rhs.q)):
                            if s ** e == rhs.q:
                                r = Rational(d, s)
                                check.extend(_vsolve(lhs.base - r, sym, **flags))
                                check.extend(_vsolve(lhs.base + r, sym, **flags))
                                check.extend(_vsolve(lhs.exp - e, sym, **flags))
                elif rhs.is_irrational:
                    b_l, e_l = lhs.base.as_base_exp()
                    n, d = (e_l * lhs.exp).as_numer_denom()
                    b, e = sqrtdenest(rhs).as_base_exp()
                    check = [sqrtdenest(i) for i in _vsolve(lhs.base - b, sym, **flags)]
                    check.extend([sqrtdenest(i) for i in _vsolve(lhs.exp - e, sym, **flags)])
                    if e_l * d != 1:
                        check.extend(_vsolve(b_l ** n - rhs ** (e_l * d), sym, **flags))
                for s in check:
                    ok = checksol(eq, sym, s)
                    if ok is None:
                        ok = eq.subs(sym, s).equals(0)
                    if ok:
                        sol.append(s)
                return list(set(sol))
        elif lhs.is_Function and len(lhs.args) == 1:
            if lhs.func in multi_inverses:
                soln = []
                for i in multi_inverses[type(lhs)](rhs):
                    soln.extend(_vsolve(lhs.args[0] - i, sym, **flags))
                return list(set(soln))
            elif lhs.func == LambertW:
                return _vsolve(lhs.args[0] - rhs * exp(rhs), sym, **flags)
        rewrite = lhs.rewrite(exp)
        rewrite = rebuild(rewrite)
        if rewrite != lhs:
            return _vsolve(rewrite - rhs, sym, **flags)
    except NotImplementedError:
        pass
    if flags.pop('bivariate', True):
        logs = eq.atoms(log)
        spow = min({i.exp for j in logs for i in j.atoms(Pow) if i.base == sym} or {1})
        if spow != 1:
            p = sym ** spow
            u = Dummy('bivariate-cov')
            ueq = eq.subs(p, u)
            if not ueq.has_free(sym):
                sol = _vsolve(ueq, u, **flags)
                inv = _vsolve(p - u, sym)
                return [i.subs(u, s) for i in inv for s in sol]
        g = _filtered_gens(eq.as_poly(), sym)
        up_or_log = set()
        for gi in g:
            if isinstance(gi, (exp, log)) or (gi.is_Pow and gi.base == S.Exp1):
                up_or_log.add(gi)
            elif gi.is_Pow:
                gisimp = powdenest(expand_power_exp(gi))
                if gisimp.is_Pow and sym in gisimp.exp.free_symbols:
                    up_or_log.add(gi)
        eq_down = expand_log(expand_power_exp(eq)).subs(dict(list(zip(up_or_log, [0] * len(up_or_log)))))
        eq = expand_power_exp(factor(eq_down, deep=True) + (eq - eq_down))
        rhs, lhs = _invert(eq, sym)
        if lhs.has(sym):
            try:
                poly = lhs.as_poly()
                g = _filtered_gens(poly, sym)
                _eq = lhs - rhs
                sols = _solve_lambert(_eq, sym, g)
                for n, s in enumerate(sols):
                    ns = nsimplify(s)
                    if ns != s and ns.count_ops() <= s.count_ops():
                        ok = checksol(_eq, sym, ns)
                        if ok is None:
                            ok = _eq.subs(sym, ns).equals(0)
                        if ok:
                            sols[n] = ns
                return sols
            except NotImplementedError:
                if len(g) == 2:
                    try:
                        gpu = bivariate_type(lhs - rhs, *g)
                        if gpu is None:
                            raise NotImplementedError
                        g, p, u = gpu
                        flags['bivariate'] = False
                        inversion = _tsolve(g - u, sym, **flags)
                        if inversion:
                            sol = _vsolve(p, u, **flags)
                            return list({i.subs(u, s) for i in inversion for s in sol})
                    except NotImplementedError:
                        pass
                else:
                    pass
    if flags.pop('force', True):
        flags['force'] = False
        pos, reps = posify(lhs - rhs)
        if rhs == S.ComplexInfinity:
            return []
        for u, s in reps.items():
            if s == sym:
                break
        else:
            u = sym
        if pos.has(u):
            try:
                soln = _vsolve(pos, u, **flags)
                return [s.subs(reps) for s in soln]
            except NotImplementedError:
                pass
        else:
            pass
    return

@conserve_mpmath_dps
def nsolve(*args, dict=False, **kwargs):
    if 'method' in kwargs:
        raise ValueError(filldedent('\n            Keyword "method" should not be used in this context.  When using\n            some mpmath solvers directly, the keyword "method" is\n            used, but when using nsolve (and findroot) the keyword to use is\n            "solver".'))
    if 'prec' in kwargs:
        import mpmath
        mpmath.mp.dps = kwargs.pop('prec')
    as_dict = dict
    from builtins import dict
    if len(args) == 3:
        f = args[0]
        fargs = args[1]
        x0 = args[2]
        if iterable(fargs) and iterable(x0):
            if len(x0) != len(fargs):
                raise TypeError('nsolve expected exactly %i guess vectors, got %i' % (len(fargs), len(x0)))
    elif len(args) == 2:
        f = args[0]
        fargs = None
        x0 = args[1]
        if iterable(f):
            raise TypeError('nsolve expected 3 arguments, got 2')
    elif len(args) < 2:
        raise TypeError('nsolve expected at least 2 arguments, got %i' % len(args))
    else:
        raise TypeError('nsolve expected at most 3 arguments, got %i' % len(args))
    modules = kwargs.get('modules', ['mpmath'])
    if iterable(f):
        f = list(f)
        for i, fi in enumerate(f):
            if isinstance(fi, Eq):
                f[i] = fi.lhs - fi.rhs
        f = Matrix(f).T
    if iterable(x0):
        x0 = list(x0)
    if not isinstance(f, Matrix):
        if isinstance(f, Eq):
            f = f.lhs - f.rhs
        elif f.is_Relational:
            raise TypeError('nsolve cannot accept inequalities')
        syms = f.free_symbols
        if fargs is None:
            fargs = syms.copy().pop()
        if not (len(syms) == 1 and (fargs in syms or fargs[0] in syms)):
            raise ValueError(filldedent('\n                expected a one-dimensional and numerical function'))
        f = lambdify(fargs, f, modules)
        x = sympify(findroot(f, x0, **kwargs))
        if as_dict:
            return [{fargs: x}]
        return x
    if len(fargs) > f.cols:
        raise NotImplementedError(filldedent('\n            need at least as many equations as variables'))
    verbose = kwargs.get('verbose', False)
    if verbose:
        print('f(x):')
        print(f)
    J = f.jacobian(fargs)
    if verbose:
        print('J(x):')
        print(J)
    f = lambdify(fargs, f.T, modules)
    J = lambdify(fargs, J, modules)
    x = findroot(f, x0, J=J, **kwargs)
    if as_dict:
        return [dict(zip(fargs, [sympify(xi) for xi in x]))]
    return Matrix(x)

def _invert(eq, *symbols, **kwargs):
    eq = sympify(eq)
    if eq.args:
        eq = eq.func(*eq.args)
    free = eq.free_symbols
    if not symbols:
        symbols = free
    if not free & set(symbols):
        return (eq, S.Zero)
    dointpow = bool(kwargs.get('integer_power', False))
    lhs = eq
    rhs = S.Zero
    while True:
        was = lhs
        while True:
            indep, dep = lhs.as_independent(*symbols)
            if lhs.is_Add:
                if indep.is_zero:
                    break
                lhs = dep
                rhs -= indep
            else:
                if indep is S.One:
                    break
                lhs = dep
                rhs /= indep
        if lhs.is_Add:
            terms = {}
            for a in lhs.args:
                i, d = a.as_independent(*symbols)
                terms.setdefault(d, []).append(i)
            if any((len(v) > 1 for v in terms.values())):
                args = []
                for d, i in terms.items():
                    if len(i) > 1:
                        args.append(Add(*i) * d)
                    else:
                        args.append(i[0] * d)
                lhs = Add(*args)
        if lhs.is_Add and (not rhs) and (len(lhs.args) == 2) and (not lhs.is_polynomial(*symbols)):
            a, b = ordered(lhs.args)
            ai, ad = a.as_independent(*symbols)
            bi, bd = b.as_independent(*symbols)
            if any((_ispow(i) for i in (ad, bd))):
                a_base, a_exp = ad.as_base_exp()
                b_base, b_exp = bd.as_base_exp()
                if a_base == b_base and a_exp.extract_additively(b_exp) is None:
                    rat = powsimp(powdenest(ad / bd))
                    lhs = rat
                    rhs = -bi / ai
                else:
                    rat = ad / bd
                    _lhs = powsimp(ad / bd)
                    if _lhs != rat:
                        lhs = _lhs
                        rhs = -bi / ai
            elif ai == -bi:
                if isinstance(ad, Function) and ad.func == bd.func:
                    if len(ad.args) == len(bd.args) == 1:
                        lhs = ad.args[0] - bd.args[0]
                    elif len(ad.args) == len(bd.args):
                        raise NotImplementedError('equal function with more than 1 argument')
                    else:
                        raise ValueError('function with different numbers of args')
        elif lhs.is_Mul and any((_ispow(a) for a in lhs.args)):
            lhs = powsimp(powdenest(lhs))
        if lhs.is_Function:
            if hasattr(lhs, 'inverse') and lhs.inverse() is not None and (len(lhs.args) == 1):
                rhs = lhs.inverse()(rhs)
                lhs = lhs.args[0]
            elif isinstance(lhs, atan2):
                y, x = lhs.args
                lhs = 2 * atan(y / (sqrt(x ** 2 + y ** 2) + x))
            elif lhs.func == rhs.func:
                if len(lhs.args) == len(rhs.args) == 1:
                    lhs = lhs.args[0]
                    rhs = rhs.args[0]
                elif len(lhs.args) == len(rhs.args):
                    raise NotImplementedError('equal function with more than 1 argument')
                else:
                    raise ValueError('function with different numbers of args')
        if rhs and lhs.is_Pow and lhs.exp.is_Integer and (lhs.exp < 0):
            lhs = 1 / lhs
            rhs = 1 / rhs
