lie_heuristics = ('abaco1_simple', 'abaco1_product', 'abaco2_similar', 'abaco2_unique_unknown', 'abaco2_unique_general', 'linear', 'function_sum', 'bivariate', 'chi')

def _ode_lie_group_try_heuristic(eq, heuristic, func, match, inf):
    xi = Function('xi')
    eta = Function('eta')
    f = func.func
    x = func.args[0]
    y = match['y']
    h = match['h']
    tempsol = []
    if not inf:
        try:
            inf = infinitesimals(eq, hint=heuristic, func=func, order=1, match=match)
        except ValueError:
            return None
    for infsim in inf:
        xiinf = infsim[xi(x, func)].subs(func, y)
        etainf = infsim[eta(x, func)].subs(func, y)
        if simplify(etainf / xiinf) == h:
            continue
        rpde = f(x, y).diff(x) * xiinf + f(x, y).diff(y) * etainf
        r = pdsolve(rpde, func=f(x, y)).rhs
        s = pdsolve(rpde - 1, func=f(x, y)).rhs
        newcoord = [_lie_group_remove(coord) for coord in [r, s]]
        r = Dummy('r')
        s = Dummy('s')
        C1 = Symbol('C1')
        rcoord = newcoord[0]
        scoord = newcoord[-1]
        try:
            sol = solve([r - rcoord, s - scoord], x, y, dict=True)
            if sol == []:
                continue
        except NotImplementedError:
            continue
        else:
            sol = sol[0]
            xsub = sol[x]
            ysub = sol[y]
            num = simplify(scoord.diff(x) + scoord.diff(y) * h)
            denom = simplify(rcoord.diff(x) + rcoord.diff(y) * h)
            if num and denom:
                diffeq = simplify((num / denom).subs([(x, xsub), (y, ysub)]))
                sep = separatevars(diffeq, symbols=[r, s], dict=True)
                if sep:
                    deq = integrate(1 / sep[s], s) + C1 - integrate(sep['coeff'] * sep[r], r)
                    deq = deq.subs([(r, rcoord), (s, scoord)])
                    try:
                        sdeq = solve(deq, y)
                    except NotImplementedError:
                        tempsol.append(deq)
                    else:
                        return [Eq(f(x), sol) for sol in sdeq]
            elif denom:
                return [Eq(f(x), solve(scoord - C1, y)[0])]
            elif num:
                return [Eq(f(x), solve(rcoord - C1, y)[0])]
    if tempsol:
        return [Eq(sol.subs(y, f(x)), 0) for sol in tempsol]
    return None

def _ode_lie_group(s, func, order, match):
    heuristics = lie_heuristics
    inf = {}
    f = func.func
    x = func.args[0]
    df = func.diff(x)
    xi = Function('xi')
    eta = Function('eta')
    xis = match['xi']
    etas = match['eta']
    y = match.pop('y', None)
    if y:
        h = -simplify(match[match['d']] / match[match['e']])
        y = y
    else:
        y = Dummy('y')
        h = s.subs(func, y)
    if xis is not None and etas is not None:
        inf = [{xi(x, f(x)): S(xis), eta(x, f(x)): S(etas)}]
        if checkinfsol(Eq(df, s), inf, func=f(x), order=1)[0][0]:
            heuristics = ['user_defined'] + list(heuristics)
    match = {'h': h, 'y': y}
    sol = None
    for heuristic in heuristics:
        sol = _ode_lie_group_try_heuristic(Eq(df, s), heuristic, func, match, inf)
        if sol:
            return sol
    return sol

def infinitesimals(eq, func=None, order=None, hint='default', match=None):
    if isinstance(eq, Equality):
        eq = eq.lhs - eq.rhs
    if not func:
        eq, func = _preprocess(eq)
    variables = func.args
    if len(variables) != 1:
        raise ValueError("ODE's have only one independent variable")
    else:
        x = variables[0]
        if not order:
            order = ode_order(eq, func)
        if order != 1:
            raise NotImplementedError("Infinitesimals for only first order ODE's have been implemented")
        else:
            df = func.diff(x)
            a = Wild('a', exclude=[df])
            b = Wild('b', exclude=[df])
            if match:
                h = match['h']
                y = match['y']
            else:
                match = collect(expand(eq), df).match(a * df + b)
                if match:
                    h = -simplify(match[b] / match[a])
                else:
                    try:
                        sol = solve(eq, df)
                    except NotImplementedError:
                        raise NotImplementedError('Infinitesimals for the first order ODE could not be found')
                    else:
                        h = sol[0]
                y = Dummy('y')
                h = h.subs(func, y)
            u = Dummy('u')
            hx = h.diff(x)
            hy = h.diff(y)
            hinv = (1 / h).subs([(x, u), (y, x)]).subs(u, y)
            match = {'h': h, 'func': func, 'hx': hx, 'hy': hy, 'y': y, 'hinv': hinv}
            if hint == 'all':
                xieta = []
                for heuristic in lie_heuristics:
                    function = globals()['lie_heuristic_' + heuristic]
                    inflist = function(match, comp=True)
                    if inflist:
                        xieta.extend([inf for inf in inflist if inf not in xieta])
                if xieta:
                    return xieta
                else:
                    raise NotImplementedError('Infinitesimals could not be found for the given ODE')
            elif hint == 'default':
                for heuristic in lie_heuristics:
                    function = globals()['lie_heuristic_' + heuristic]
                    xieta = function(match, comp=False)
                    if xieta:
                        return xieta
                raise NotImplementedError('Infinitesimals could not be found for the given ODE')
            elif hint not in lie_heuristics:
                raise ValueError('Heuristic not recognized: ' + hint)
            else:
                function = globals()['lie_heuristic_' + hint]
                xieta = function(match, comp=True)
                if xieta:
                    return xieta
                else:
                    raise ValueError('Infinitesimals could not be found using the given heuristic')

