                xypart = term / rem
                if xypart not in coeffdict:
                    coeffdict[xypart] = rem
                else:
                    coeffdict[xypart] += rem
            elif term not in coeffdict:
                coeffdict[term] = S.One
            else:
                coeffdict[term] += S.One
