    z_x = dsolve(diff(fw(u), u) - ((b * F1 - a * F2) / (c * F2 - b * F3)).subs(v, y_zx).subs(w, fw(u))).rhs
    z_y = dsolve(diff(fw(v), v) - ((b * F1 - a * F2) / (a * F3 - c * F1)).subs(u, x_yz).subs(w, fw(v))).rhs
