    def _get_general_solution(self, *, simplify_flag: bool=True):
        f = self.ode_problem.func.func
        x = self.ode_problem.sym
        C1, C2 = self.ode_problem.get_numbered_constants(num=2)
        b = self.rn['b']
        m = self.rn['m']
        if m.is_positive:
            arg = -b / cbrt(m) ** 2 - cbrt(m) * x
