        _value_check(mu.is_real is not False, 'Location parameter must be real')

    def _logit(self, x):
        return log(x / (1 - x))

    def pdf(self, x):
        mu, s = (self.mu, self.s)
        return exp(-(self._logit(x) - mu) ** 2 / (2 * s ** 2)) * (S.One / sqrt(2 * pi * s ** 2)) * (1 / (x * (1 - x)))

    def _cdf(self, x):
        mu, s = (self.mu, self.s)
        return S.One / 2 * (1 + erf((self._logit(x) - mu) / sqrt(2 * s ** 2)))

