from .core import chain, identity, do_one

def top_down(brule, fns=basic_fns):
    return chain(do_one(brule, identity), lambda expr: sall(top_down(brule, fns), fns)(expr))

def sall(brule, fns=basic_fns):
    op, new, children, leaf = map(fns.get, ('op', 'new', 'children', 'leaf'))

    def all_rl(expr):
        if leaf(expr):
            yield expr
        else:
            myop = op(expr)
            argss = product(*map(brule, children(expr)))
            for args in argss:
                yield new(myop, *args)
    return all_rl

