            metrics = [_.data for _ in self.index_types]
            marray = self.data
            marraydim = marray.rank()
            for metric in metrics:
                marray = tensorproduct(marray, metric, marray)
                marray = tensorcontraction(marray, (0, marraydim), (marraydim + 1, marraydim + 2))
