        if isinstance(index, (SYMPY_INTS, Integer, slice)):
            index = (index,)
        if len(index) < self.rank():
            index = tuple(index) + tuple((slice(None) for i in range(len(index), self.rank())))
        if len(index) > self.rank():
            raise ValueError('Dimension of index greater than rank of array')
