        cumulative_subranks = [0] + list(accumulate(subranks))
        for i in range(len(subranks)):
            s = {index2arg[new_permutation[j]] for j in range(cumulative_subranks[i], cumulative_subranks[i + 1])}
            if len(s) != 1:
                continue
            elem = next(iter(s))
            if i != elem:
