def _(expr: ArraySymbol, x: _ArrayExpr):
    if expr == x:
        return _permute_dims(ArrayTensorProduct.fromiter((Identity(i) for i in expr.shape)), [2 * i for i in range(len(expr.shape))] + [2 * i + 1 for i in range(len(expr.shape))])
    return ZeroArray(*x.shape + expr.shape)

@array_derive.register(MatrixSymbol)
def _(expr: MatrixSymbol, x: _ArrayExpr):
    m, n = expr.shape
    if expr == x:
        return _permute_dims(_array_tensor_product(Identity(m), Identity(n)), [0, 2, 1, 3])
    return ZeroArray(*x.shape + expr.shape)

