    class ExceptionInfo:

        def __init__(self, value):
            self.value = value

        def __repr__(self):
            return '<ExceptionInfo {!r}>'.format(self.value)

    def raises(expectedException, code=None):
        if code is None:
            return RaisesContext(expectedException)
        elif callable(code):
            try:
                code()
            except expectedException as e:
                return ExceptionInfo(e)
            raise Failed('DID NOT RAISE')
        elif isinstance(code, str):
            raise TypeError('\'raises(xxx, "code")\' has been phased out; change \'raises(xxx, "expression")\' to \'raises(xxx, lambda: expression)\', \'raises(xxx, "statement")\' to \'with raises(xxx): statement\'')
        else:
            raise TypeError('raises() expects a callable for the 2nd argument.')

    class RaisesContext:

        def __init__(self, expectedException):
            self.expectedException = expectedException

        def __enter__(self):
            return None

        def __exit__(self, exc_type, exc_value, traceback):
            if exc_type is None:
                raise Failed('DID NOT RAISE')
            return issubclass(exc_type, self.expectedException)

    class XFail(Exception):
