                func()
            except Exception as e:
                message = str(e)
                if message != 'Timeout':
                    raise XFail(func.__name__)
                else:
                    raise Skipped('Timeout')
            raise XPass(func.__name__)
        wrapper = functools.update_wrapper(wrapper, func)
        return wrapper

