    if import_module('matplotlib') is not None:
        import matplotlib
        matplotlib.use('Agg')
    import sympy.external
    sympy.external.importtools.WARN_OLD_VERSION = False
    sympy.external.importtools.WARN_NOT_INSTALLED = False
    from sympy.plotting.plot import unset_show
    unset_show()
    r = PyTestReporter(verbose, split=split, colors=colors, force_colors=force_colors)
    t = SymPyDocTests(r, normal)
    test_files = t.get_test_files('sympy')
    test_files.extend(t.get_test_files('examples', init_only=False))
    not_blacklisted = [f for f in test_files if not any((b in f for b in blacklist))]
    if len(paths) == 0:
        matched = not_blacklisted
    else:
        paths = convert_to_native_paths(paths)
        matched = []
        for f in not_blacklisted:
            basename = os.path.basename(f)
            for p in paths:
                if p in f or fnmatch(basename, p):
                    matched.append(f)
                    break
    matched.sort()
    if split:
        matched = split_list(matched, split)
    t._testfiles.extend(matched)
    if t._testfiles:
        failed = not t.test()
    else:
        failed = False
    test_files_rst = t.get_test_files('doc/src', '*.rst', init_only=False)
    test_files_md = t.get_test_files('doc/src', '*.md', init_only=False)
    test_files = test_files_rst + test_files_md
    test_files.sort()
    not_blacklisted = [f for f in test_files if not any((b in f for b in blacklist))]
    if len(paths) == 0:
        matched = not_blacklisted
    else:
        matched = []
        for f in not_blacklisted:
            basename = os.path.basename(f)
            for p in paths:
                if p in f or fnmatch(basename, p):
                    matched.append(f)
                    break
    if split:
        matched = split_list(matched, split)
    first_report = True
    for rst_file in matched:
        if not os.path.isfile(rst_file):
            continue
        old_displayhook = sys.displayhook
        try:
            use_unicode_prev, wrap_line_prev = setup_pprint()
            out = sympytestfile(rst_file, module_relative=False, encoding='utf-8', optionflags=pdoctest.ELLIPSIS | pdoctest.NORMALIZE_WHITESPACE | pdoctest.IGNORE_EXCEPTION_DETAIL)
        finally:
            sys.displayhook = old_displayhook
            import sympy.interactive.printing as interactive_printing
            interactive_printing.NO_GLOBAL = False
            pprint_use_unicode(use_unicode_prev)
            stringpict._GLOBAL_WRAP_LINE = wrap_line_prev
        rstfailed, tested = out
        if tested:
            failed = rstfailed or failed
            if first_report:
                first_report = False
                msg = 'rst/md doctests start'
                if not t._testfiles:
                    r.start(msg=msg)
                else:
                    r.write_center(msg)
                    print()
            file_id = rst_file[rst_file.find('sympy') + len('sympy') + 1:]
            print(file_id, end=' ')
            wid = r.terminal_width - len(file_id) - 1
            test_file = '[%s]' % tested
            report = '[%s]' % (rstfailed or 'OK')
            print(''.join([test_file, ' ' * (wid - len(test_file) - len(report)), report]))
    if not first_report and failed:
        print()
        print('DO *NOT* COMMIT!')
    return int(failed)
sp = re.compile('([0-9]+)/([1-9][0-9]*)')

def split_list(l, split, density=None):
    m = sp.match(split)
    if not m:
        raise ValueError('split must be a string of the form a/b where a and b are ints')
    i, t = map(int, m.groups())
    if not density:
        return l[(i - 1) * len(l) // t:i * len(l) // t]
    tot = sum(density)
    density = [x / tot for x in density]

    def density_inv(x):
        if x <= 0:
            return 0
        if x >= sum(density):
            return 1
        cumm = 0
        for i, d in enumerate(density):
            cumm += d
            if cumm >= x:
                break
        frac = (d - (cumm - x)) / d
        return (i + frac) / len(density)
    lower_frac = density_inv((i - 1) / t)
    higher_frac = density_inv(i / t)
    return l[int(lower_frac * len(l)):int(higher_frac * len(l))]
from collections import namedtuple
SymPyTestResults = namedtuple('SymPyTestResults', 'failed attempted')

def sympytestfile(filename, module_relative=True, name=None, package=None, globs=None, verbose=None, report=True, optionflags=0, extraglobs=None, raise_on_error=False, parser=pdoctest.DocTestParser(), encoding=None):
    if package and (not module_relative):
        raise ValueError('Package may only be specified for module-relative paths.')
    text, filename = pdoctest._load_testfile(filename, package, module_relative, encoding)
    if name is None:
        name = os.path.basename(filename)
    if globs is None:
        globs = {}
    else:
        globs = globs.copy()
    if extraglobs is not None:
        globs.update(extraglobs)
    if '__name__' not in globs:
        globs['__name__'] = '__main__'
    if raise_on_error:
        runner = pdoctest.DebugRunner(verbose=verbose, optionflags=optionflags)
    else:
        runner = SymPyDocTestRunner(verbose=verbose, optionflags=optionflags)
        runner._checker = SymPyOutputChecker()
    test = parser.get_doctest(text, globs, name, filename, 0)
    runner.run(test)
    if report:
        runner.summarize()
    if pdoctest.master is None:
        pdoctest.master = runner
    else:
        pdoctest.master.merge(runner)
    return SymPyTestResults(runner.failures, runner.tries)

class SymPyTests:

    def __init__(self, reporter, kw='', post_mortem=False, seed=None, fast_threshold=None, slow_threshold=None):
        self._post_mortem = post_mortem
        self._kw = kw
        self._count = 0
        self._root_dir = get_sympy_dir()
        self._reporter = reporter
        self._reporter.root_dir(self._root_dir)
        self._testfiles = []
        self._seed = seed if seed is not None else random.random()
        if fast_threshold:
            self._fast_threshold = float(fast_threshold)
        else:
            self._fast_threshold = 8
        if slow_threshold:
            self._slow_threshold = float(slow_threshold)
        else:
            self._slow_threshold = 10

    def test(self, sort=False, timeout=False, slow=False, enhance_asserts=False, fail_on_timeout=False):
        if sort:
            self._testfiles.sort()
        elif slow:
            pass
        else:
            random.seed(self._seed)
            random.shuffle(self._testfiles)
        self._reporter.start(self._seed)
        for f in self._testfiles:
            try:
                self.test_file(f, sort, timeout, slow, enhance_asserts, fail_on_timeout)
            except KeyboardInterrupt:
                print(' interrupted by user')
                self._reporter.finish()
                raise
        return self._reporter.finish()

    def _enhance_asserts(self, source):
        from ast import NodeTransformer, Compare, Name, Store, Load, Tuple, Assign, BinOp, Str, Mod, Assert, parse, fix_missing_locations
        ops = {'Eq': '==', 'NotEq': '!=', 'Lt': '<', 'LtE': '<=', 'Gt': '>', 'GtE': '>=', 'Is': 'is', 'IsNot': 'is not', 'In': 'in', 'NotIn': 'not in'}

        class Transform(NodeTransformer):

            def visit_Assert(self, stmt):
                if isinstance(stmt.test, Compare):
                    compare = stmt.test
                    values = [compare.left] + compare.comparators
                    names = ['_%s' % i for i, _ in enumerate(values)]
                    names_store = [Name(n, Store()) for n in names]
                    names_load = [Name(n, Load()) for n in names]
                    target = Tuple(names_store, Store())
                    value = Tuple(values, Load())
                    assign = Assign([target], value)
                    new_compare = Compare(names_load[0], compare.ops, names_load[1:])
                    msg_format = '\n%s ' + '\n%s '.join([ops[op.__class__.__name__] for op in compare.ops]) + '\n%s'
                    msg = BinOp(Str(msg_format), Mod(), Tuple(names_load, Load()))
                    test = Assert(new_compare, msg, lineno=stmt.lineno, col_offset=stmt.col_offset)
                    return [assign, test]
                else:
                    return stmt
        tree = parse(source)
        new_tree = Transform().visit(tree)
        return fix_missing_locations(new_tree)

    def test_file(self, filename, sort=True, timeout=False, slow=False, enhance_asserts=False, fail_on_timeout=False):
        reporter = self._reporter
        funcs = []
        try:
            gl = {'__file__': filename}
            try:
                open_file = lambda: open(filename, encoding='utf8')
                with open_file() as f:
                    source = f.read()
                    if self._kw:
                        for l in source.splitlines():
                            if l.lstrip().startswith('def '):
                                if any((l.lower().find(k.lower()) != -1 for k in self._kw)):
                                    break
                        else:
                            return
                if enhance_asserts:
                    try:
                        source = self._enhance_asserts(source)
                    except ImportError:
                        pass
                code = compile(source, filename, 'exec', flags=0, dont_inherit=True)
                exec(code, gl)
            except (SystemExit, KeyboardInterrupt):
                raise
            except ImportError:
                reporter.import_error(filename, sys.exc_info())
                return
            except Exception:
                reporter.test_exception(sys.exc_info())
            clear_cache()
            self._count += 1
            random.seed(self._seed)
            disabled = gl.get('disabled', False)
            if not disabled:
                funcs = []
                for f in gl:
                    if f.startswith('test_') and (inspect.isfunction(gl[f]) or inspect.ismethod(gl[f])):
                        func = gl[f]
                        while hasattr(func, '__wrapped__'):
                            func = func.__wrapped__
                        if inspect.getsourcefile(func) == filename:
                            funcs.append(gl[f])
                if slow:
                    funcs = [f for f in funcs if getattr(f, '_slow', False)]
                funcs.sort(key=lambda x: inspect.getsourcelines(x)[1])
                i = 0
                while i < len(funcs):
                    if inspect.isgeneratorfunction(funcs[i]):
                        f = funcs.pop(i)
                        for fg in f():
                            func = fg[0]
                            args = fg[1:]
                            fgw = lambda: func(*args)
                            funcs.insert(i, fgw)
                            i += 1
                    else:
                        i += 1
                funcs = [x for x in funcs if self.matches(x)]
            if not funcs:
                return
        except Exception:
            reporter.entering_filename(filename, len(funcs))
            raise
        reporter.entering_filename(filename, len(funcs))
        if not sort:
            random.shuffle(funcs)
        for f in funcs:
            start = time.time()
            reporter.entering_test(f)
            try:
                if getattr(f, '_slow', False) and (not slow):
                    raise Skipped('Slow')
                with raise_on_deprecated():
                    if timeout:
                        self._timeout(f, timeout, fail_on_timeout)
                    else:
                        random.seed(self._seed)
                        f()
            except KeyboardInterrupt:
                if getattr(f, '_slow', False):
                    reporter.test_skip('KeyboardInterrupt')
                else:
                    raise
            except Exception:
                if timeout:
                    signal.alarm(0)
                t, v, tr = sys.exc_info()
                if t is AssertionError:
                    reporter.test_fail((t, v, tr))
                    if self._post_mortem:
                        pdb.post_mortem(tr)
                elif t.__name__ == 'Skipped':
                    reporter.test_skip(v)
                elif t.__name__ == 'XFail':
                    reporter.test_xfail()
                elif t.__name__ == 'XPass':
                    reporter.test_xpass(v)
                else:
                    reporter.test_exception((t, v, tr))
                    if self._post_mortem:
                        pdb.post_mortem(tr)
            else:
                reporter.test_pass()
            taken = time.time() - start
            if taken > self._slow_threshold:
                filename = os.path.relpath(filename, reporter._root_dir)
                reporter.slow_test_functions.append((filename + '::' + f.__name__, taken))
            if getattr(f, '_slow', False) and slow:
                if taken < self._fast_threshold:
                    filename = os.path.relpath(filename, reporter._root_dir)
                    reporter.fast_test_functions.append((filename + '::' + f.__name__, taken))
        reporter.leaving_filename()

    def _timeout(self, function, timeout, fail_on_timeout):

        def callback(x, y):
            signal.alarm(0)
            if fail_on_timeout:
                raise TimeOutError('Timed out after %d seconds' % timeout)
            else:
                raise Skipped('Timeout')
        signal.signal(signal.SIGALRM, callback)
        signal.alarm(timeout)
        function()
        signal.alarm(0)

    def matches(self, x):
        if not self._kw:
            return True
        for kw in self._kw:
            if x.__name__.lower().find(kw.lower()) != -1:
                return True
        return False

    def get_test_files(self, dir, pat='test_*.py'):
        dir = os.path.join(self._root_dir, convert_to_native_paths([dir])[0])
        g = []
        for path, folders, files in os.walk(dir):
            g.extend([os.path.join(path, f) for f in files if fnmatch(f, pat)])
        return sorted([os.path.normcase(gi) for gi in g])

class SymPyDocTests:

    def __init__(self, reporter, normal):
        self._count = 0
        self._root_dir = get_sympy_dir()
        self._reporter = reporter
        self._reporter.root_dir(self._root_dir)
        self._normal = normal
        self._testfiles = []

    def test(self):
        self._reporter.start()
        for f in self._testfiles:
            try:
                self.test_file(f)
            except KeyboardInterrupt:
                print(' interrupted by user')
                self._reporter.finish()
                raise
        return self._reporter.finish()

    def test_file(self, filename):
        clear_cache()
        from io import StringIO
        import sympy.interactive.printing as interactive_printing
        from sympy.printing.pretty.pretty import pprint_use_unicode
        from sympy.printing.pretty import stringpict
        rel_name = filename[len(self._root_dir) + 1:]
        dirname, file = os.path.split(filename)
        module = rel_name.replace(os.sep, '.')[:-3]
        if rel_name.startswith('examples'):
            sys.path.insert(0, dirname)
            module = file[:-3]
        try:
            module = pdoctest._normalize_module(module)
            tests = SymPyDocTestFinder().find(module)
        except (SystemExit, KeyboardInterrupt):
            raise
        except ImportError:
            self._reporter.import_error(filename, sys.exc_info())
            return
        finally:
            if rel_name.startswith('examples'):
                del sys.path[0]
        tests = [test for test in tests if len(test.examples) > 0]
        tests.sort(key=lambda x: -x.lineno)
        if not tests:
            return
        self._reporter.entering_filename(filename, len(tests))
        for test in tests:
            assert len(test.examples) != 0
            if self._reporter._verbose:
                self._reporter.write('\n{} '.format(test.name))
            if '_doctest_depends_on' in test.globs:
                try:
                    self._check_dependencies(**test.globs['_doctest_depends_on'])
                except DependencyError as e:
                    self._reporter.test_skip(v=str(e))
                    continue
            runner = SymPyDocTestRunner(verbose=self._reporter._verbose == 2, optionflags=pdoctest.ELLIPSIS | pdoctest.NORMALIZE_WHITESPACE | pdoctest.IGNORE_EXCEPTION_DETAIL)
            runner._checker = SymPyOutputChecker()
            old = sys.stdout
            new = old if self._reporter._verbose == 2 else StringIO()
            sys.stdout = new
            if not self._normal:
                test.globs = {}
            old_displayhook = sys.displayhook
            use_unicode_prev, wrap_line_prev = setup_pprint()
            try:
                f, t = runner.run(test, out=new.write, clear_globs=False)
            except KeyboardInterrupt:
                raise
            finally:
                sys.stdout = old
            if f > 0:
                self._reporter.doctest_fail(test.name, new.getvalue())
            else:
                self._reporter.test_pass()
                sys.displayhook = old_displayhook
                interactive_printing.NO_GLOBAL = False
                pprint_use_unicode(use_unicode_prev)
                stringpict._GLOBAL_WRAP_LINE = wrap_line_prev
        self._reporter.leaving_filename()

    def get_test_files(self, dir, pat='*.py', init_only=True):

        def importable(x):
            init_py = os.path.join(os.path.dirname(x), '__init__.py')
            return os.path.exists(init_py)
        dir = os.path.join(self._root_dir, convert_to_native_paths([dir])[0])
        g = []
        for path, folders, files in os.walk(dir):
            g.extend([os.path.join(path, f) for f in files if not f.startswith('test_') and fnmatch(f, pat)])
        if init_only:
            g = [x for x in g if importable(x)]
        return [os.path.normcase(gi) for gi in g]

    def _check_dependencies(self, executables=(), modules=(), disable_viewers=(), python_version=(3, 5), ground_types=None):
        for executable in executables:
            if not shutil.which(executable):
                raise DependencyError('Could not find %s' % executable)
        for module in modules:
            if module == 'matplotlib':
                matplotlib = import_module('matplotlib', import_kwargs={'fromlist': ['pyplot', 'cm', 'collections']}, min_module_version='1.0.0', catch=(RuntimeError,))
                if matplotlib is None:
                    raise DependencyError('Could not import matplotlib')
            elif not import_module(module):
                raise DependencyError('Could not import %s' % module)
        if disable_viewers:
            tempdir = tempfile.mkdtemp()
            os.environ['PATH'] = '%s:%s' % (tempdir, os.environ['PATH'])
            vw = '#!/usr/bin/env python3\nimport sys\nif len(sys.argv) <= 1:\n    exit("wrong number of args")\n'
            for viewer in disable_viewers:
                with open(os.path.join(tempdir, viewer), 'w') as fh:
                    fh.write(vw)
                os.chmod(os.path.join(tempdir, viewer), stat.S_IREAD | stat.S_IWRITE | stat.S_IXUSR)
        if python_version:
            if sys.version_info < python_version:
                raise DependencyError('Requires Python >= ' + '.'.join(map(str, python_version)))
        if ground_types is not None:
            if GROUND_TYPES not in ground_types:
                raise DependencyError('Requires ground_types in ' + str(ground_types))
        if 'pyglet' in modules:
            import pyglet

            class DummyWindow:

                def __init__(self, *args, **kwargs):
                    self.has_exit = True
                    self.width = 600
                    self.height = 400

                def set_vsync(self, x):
                    pass

                def switch_to(self):
                    pass

                def push_handlers(self, x):
                    pass

                def close(self):
                    pass
            pyglet.window.Window = DummyWindow

class SymPyDocTestFinder(DocTestFinder):

    def _find(self, tests, obj, name, module, source_lines, globs, seen):
        if self._verbose:
            print('Finding tests in %s' % name)
        if id(obj) in seen:
            return
        seen[id(obj)] = 1
        if inspect.isclass(obj):
            if obj.__module__.split('.')[0] != 'sympy':
                return
        test = self._get_test(obj, name, module, globs, source_lines)
        if test is not None:
            tests.append(test)
        if not self._recurse:
            return
        if inspect.ismodule(obj):
            for rawname, val in obj.__dict__.items():
                if inspect.isfunction(val) or inspect.isclass(val):
                    if val.__module__ != module.__name__:
                        continue
                    assert self._from_module(module, val), '%s is not in module %s (rawname %s)' % (val, module, rawname)
                    try:
                        valname = '%s.%s' % (name, rawname)
                        self._find(tests, val, valname, module, source_lines, globs, seen)
                    except KeyboardInterrupt:
                        raise
            for valname, val in getattr(obj, '__test__', {}).items():
                if not isinstance(valname, str):
                    raise ValueError('SymPyDocTestFinder.find: __test__ keys must be strings: %r' % (type(valname),))
                if not (inspect.isfunction(val) or inspect.isclass(val) or inspect.ismethod(val) or inspect.ismodule(val) or isinstance(val, str)):
                    raise ValueError('SymPyDocTestFinder.find: __test__ values must be strings, functions, methods, classes, or modules: %r' % (type(val),))
                valname = '%s.__test__.%s' % (name, valname)
                self._find(tests, val, valname, module, source_lines, globs, seen)
        if inspect.isclass(obj):
            for valname, val in obj.__dict__.items():
                if isinstance(val, staticmethod):
                    val = getattr(obj, valname)
                if isinstance(val, classmethod):
                    val = getattr(obj, valname).__func__
                if (inspect.isfunction(unwrap(val)) or inspect.isclass(val) or isinstance(val, property)) and self._from_module(module, val):
                    if isinstance(val, property):
                        if hasattr(val.fget, '__module__'):
                            if val.fget.__module__ != module.__name__:
                                continue
                    elif val.__module__ != module.__name__:
                        continue
                    assert self._from_module(module, val), '%s is not in module %s (valname %s)' % (val, module, valname)
                    valname = '%s.%s' % (name, valname)
                    self._find(tests, val, valname, module, source_lines, globs, seen)

    def _get_test(self, obj, name, module, globs, source_lines):
        lineno = None
        if isinstance(obj, str):
            docstring = obj
            matches = re.findall('line \\d+', name)
            assert len(matches) == 1, "string '%s' does not contain lineno " % name
            lineno = int(matches[0][5:])
        else:
            docstring = getattr(obj, '__doc__', '')
            if docstring is None:
                docstring = ''
            if not isinstance(docstring, str):
                docstring = str(docstring)
        if self._exclude_empty and (not docstring):
            return None
        if isinstance(obj, property):
            if obj.fget.__doc__ is None:
                return None
        if lineno is None:
            obj = unwrap(obj)
            if hasattr(obj, 'func_closure') and obj.func_closure is not None:
                tobj = obj.func_closure[0].cell_contents
            elif isinstance(obj, property):
                tobj = obj.fget
            else:
                tobj = obj
            lineno = self._find_lineno(tobj, source_lines)
        if lineno is None:
            return None
        if module is None:
            filename = None
        else:
            filename = getattr(module, '__file__', module.__name__)
            if filename[-4:] in ('.pyc', '.pyo'):
                filename = filename[:-1]
        globs['_doctest_depends_on'] = getattr(obj, '_doctest_depends_on', {})
        return self._parser.get_doctest(docstring, globs, name, filename, lineno)

class SymPyDocTestRunner(DocTestRunner):

    def run(self, test, compileflags=None, out=None, clear_globs=True):
        self.test = test
        for example in test.examples:
            example.want = example.want.replace('```\n', '')
            example.exc_msg = example.exc_msg and example.exc_msg.replace('```\n', '')
        if compileflags is None:
            compileflags = pdoctest._extract_future_flags(test.globs)
        save_stdout = sys.stdout
        if out is None:
            out = save_stdout.write
        sys.stdout = self._fakeout
        save_set_trace = pdb.set_trace
        self.debugger = pdoctest._OutputRedirectingPdb(save_stdout)
        self.debugger.reset()
        pdb.set_trace = self.debugger.set_trace
        self.save_linecache_getlines = pdoctest.linecache.getlines
        linecache.getlines = self.__patched_linecache_getlines
        with raise_on_deprecated():
            try:
                return self.__run(test, compileflags, out)
            finally:
                sys.stdout = save_stdout
                pdb.set_trace = save_set_trace
                linecache.getlines = self.save_linecache_getlines
                if clear_globs:
                    test.globs.clear()
monkeypatched_methods = ['patched_linecache_getlines', 'run', 'record_outcome']
for method in monkeypatched_methods:
    oldname = '_DocTestRunner__' + method
    newname = '_SymPyDocTestRunner__' + method
    setattr(SymPyDocTestRunner, newname, getattr(DocTestRunner, oldname))

class SymPyOutputChecker(pdoctest.OutputChecker):

    def __init__(self):
        got_floats = '(\\d+\\.\\d*|\\.\\d+)'
        want_floats = got_floats + '(\\.{3})?'
        front_sep = '\\s|\\+|\\-|\\*|,'
        back_sep = front_sep + '|j|e'
        fbeg = '^%s(?=%s|$)' % (got_floats, back_sep)
        fmidend = '(?<=%s)%s(?=%s|$)' % (front_sep, got_floats, back_sep)
        self.num_got_rgx = re.compile('(%s|%s)' % (fbeg, fmidend))
        fbeg = '^%s(?=%s|$)' % (want_floats, back_sep)
        fmidend = '(?<=%s)%s(?=%s|$)' % (front_sep, want_floats, back_sep)
        self.num_want_rgx = re.compile('(%s|%s)' % (fbeg, fmidend))

    def check_output(self, want, got, optionflags):
        if got == want:
            return True
        matches = self.num_got_rgx.finditer(got)
        numbers_got = [match.group(1) for match in matches]
        matches = self.num_want_rgx.finditer(want)
        numbers_want = [match.group(1) for match in matches]
        if len(numbers_got) != len(numbers_want):
            return False
        if len(numbers_got) > 0:
            nw_ = []
            for ng, nw in zip(numbers_got, numbers_want):
                if '...' in nw:
                    nw_.append(ng)
                    continue
                else:
                    nw_.append(nw)
                if abs(float(ng) - float(nw)) > 1e-05:
                    return False
            got = self.num_got_rgx.sub('%s', got)
            got = got % tuple(nw_)
        if not optionflags & pdoctest.DONT_ACCEPT_BLANKLINE:
            want = re.sub('(?m)^%s\\s*?$' % re.escape(pdoctest.BLANKLINE_MARKER), '', want)
            got = re.sub('(?m)^\\s*?$', '', got)
            if got == want:
                return True
        if optionflags & pdoctest.NORMALIZE_WHITESPACE:
            got = ' '.join(got.split())
            want = ' '.join(want.split())
            if got == want:
                return True
        if optionflags & pdoctest.ELLIPSIS:
            if pdoctest._ellipsis_match(want, got):
                return True
        return False

class Reporter:
    pass

class PyTestReporter(Reporter):

    def __init__(self, verbose=False, tb='short', colors=True, force_colors=False, split=None):
        self._verbose = verbose
        self._tb_style = tb
        self._colors = colors
        self._force_colors = force_colors
        self._xfailed = 0
        self._xpassed = []
        self._failed = []
        self._failed_doctest = []
        self._passed = 0
        self._skipped = 0
        self._exceptions = []
        self._terminal_width = None
        self._default_width = 80
        self._split = split
        self._active_file = ''
        self._active_f = None
        self.slow_test_functions = []
        self.fast_test_functions = []
        self._write_pos = 0
        self._line_wrap = False

    def root_dir(self, dir):
        self._root_dir = dir

    @property
    def terminal_width(self):
        if self._terminal_width is not None:
            return self._terminal_width

        def findout_terminal_width():
            if sys.platform == 'win32':
                from ctypes import windll, create_string_buffer
                h = windll.kernel32.GetStdHandle(-12)
                csbi = create_string_buffer(22)
                res = windll.kernel32.GetConsoleScreenBufferInfo(h, csbi)
                if res:
                    import struct
                    _, _, _, _, _, left, _, right, _, _, _ = struct.unpack('hhhhHhhhhhh', csbi.raw)
                    return right - left
                else:
                    return self._default_width
            if hasattr(sys.stdout, 'isatty') and (not sys.stdout.isatty()):
                return self._default_width
            try:
                process = subprocess.Popen(['stty', '-a'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                stdout, stderr = process.communicate()
                stdout = stdout.decode('utf-8')
            except OSError:
                pass
            else:
                re_linux = 'columns\\s+(?P<columns>\\d+);'
                re_osx = '(?P<columns>\\d+)\\s*columns;'
                re_solaris = 'columns\\s+=\\s+(?P<columns>\\d+);'
                for regex in (re_linux, re_osx, re_solaris):
                    match = re.search(regex, stdout)
                    if match is not None:
                        columns = match.group('columns')
                        try:
                            width = int(columns)
                        except ValueError:
                            pass
                        if width != 0:
                            return width
            return self._default_width
        width = findout_terminal_width()
        self._terminal_width = width
        return width

    def write(self, text, color='', align='left', width=None, force_colors=False):
        color_templates = (('Black', '0;30'), ('Red', '0;31'), ('Green', '0;32'), ('Brown', '0;33'), ('Blue', '0;34'), ('Purple', '0;35'), ('Cyan', '0;36'), ('LightGray', '0;37'), ('DarkGray', '1;30'), ('LightRed', '1;31'), ('LightGreen', '1;32'), ('Yellow', '1;33'), ('LightBlue', '1;34'), ('LightPurple', '1;35'), ('LightCyan', '1;36'), ('White', '1;37'))
        colors = {}
        for name, value in color_templates:
            colors[name] = value
        c_normal = '\x1b[0m'
        c_color = '\x1b[%sm'
        if width is None:
            width = self.terminal_width
        if align == 'right':
            if self._write_pos + len(text) > width:
                self.write('\n')
            self.write(' ' * (width - self._write_pos - len(text)))
        if not self._force_colors and hasattr(sys.stdout, 'isatty') and (not sys.stdout.isatty()):
            color = ''
        elif sys.platform == 'win32':
            color = ''
        elif not self._colors:
            color = ''
        if self._line_wrap:
            if text[0] != '\n':
                sys.stdout.write('\n')
        if IS_WINDOWS:
            text = text.encode('raw_unicode_escape').decode('utf8', 'ignore')
        elif not sys.stdout.encoding.lower().startswith('utf'):
            text = text.encode(sys.stdout.encoding, 'backslashreplace').decode(sys.stdout.encoding)
        if color == '':
            sys.stdout.write(text)
        else:
            sys.stdout.write('%s%s%s' % (c_color % colors[color], text, c_normal))
        sys.stdout.flush()
        l = text.rfind('\n')
        if l == -1:
            self._write_pos += len(text)
        else:
            self._write_pos = len(text) - l - 1
        self._line_wrap = self._write_pos >= width
        self._write_pos %= width

    def write_center(self, text, delim='='):
        width = self.terminal_width
        if text != '':
            text = ' %s ' % text
        idx = (width - len(text)) // 2
        t = delim * idx + text + delim * (width - idx - len(text))
        self.write(t + '\n')

    def write_exception(self, e, val, tb):
        tb = tb.tb_next
        t = traceback.format_exception(e, val, tb)
        self.write(''.join(t))

    def start(self, seed=None, msg='test process starts'):
        self.write_center(msg)
        executable = sys.executable
        v = tuple(sys.version_info)
        python_version = '%s.%s.%s-%s-%s' % v
        implementation = platform.python_implementation()
        if implementation == 'PyPy':
            implementation += ' %s.%s.%s-%s-%s' % sys.pypy_version_info
        self.write('executable:         %s  (%s) [%s]\n' % (executable, python_version, implementation))
        from sympy.utilities.misc import ARCH
        self.write('architecture:       %s\n' % ARCH)
        from sympy.core.cache import USE_CACHE
        self.write('cache:              %s\n' % USE_CACHE)
        version = ''
        if GROUND_TYPES == 'gmpy':
            import gmpy2 as gmpy
            version = gmpy.version()
        self.write('ground types:       %s %s\n' % (GROUND_TYPES, version))
        numpy = import_module('numpy')
        self.write('numpy:              %s\n' % (None if not numpy else numpy.__version__))
        if seed is not None:
            self.write('random seed:        %d\n' % seed)
        from sympy.utilities.misc import HASH_RANDOMIZATION
        self.write('hash randomization: ')
        hash_seed = os.getenv('PYTHONHASHSEED') or '0'
        if HASH_RANDOMIZATION and (hash_seed == 'random' or int(hash_seed)):
            self.write('on (PYTHONHASHSEED=%s)\n' % hash_seed)
        else:
            self.write('off\n')
        if self._split:
            self.write('split:              %s\n' % self._split)
        self.write('\n')
        self._t_start = clock()

    def finish(self):
        self._t_end = clock()
        self.write('\n')
        global text, linelen
        text = 'tests finished: %d passed, ' % self._passed
        linelen = len(text)

        def add_text(mytext):
            global text, linelen
            'Break new text if too long.'
            if linelen + len(mytext) > self.terminal_width:
                text += '\n'
                linelen = 0
            text += mytext
            linelen += len(mytext)
        if len(self._failed) > 0:
            add_text('%d failed, ' % len(self._failed))
        if len(self._failed_doctest) > 0:
            add_text('%d failed, ' % len(self._failed_doctest))
        if self._skipped > 0:
            add_text('%d skipped, ' % self._skipped)
        if self._xfailed > 0:
            add_text('%d expected to fail, ' % self._xfailed)
        if len(self._xpassed) > 0:
            add_text('%d expected to fail but passed, ' % len(self._xpassed))
        if len(self._exceptions) > 0:
            add_text('%d exceptions, ' % len(self._exceptions))
        add_text('in %.2f seconds' % (self._t_end - self._t_start))
        if self.slow_test_functions:
            self.write_center('slowest tests', '_')
            sorted_slow = sorted(self.slow_test_functions, key=lambda r: r[1])
            for slow_func_name, taken in sorted_slow:
                print('%s - Took %.3f seconds' % (slow_func_name, taken))
        if self.fast_test_functions:
            self.write_center('unexpectedly fast tests', '_')
            sorted_fast = sorted(self.fast_test_functions, key=lambda r: r[1])
            for fast_func_name, taken in sorted_fast:
                print('%s - Took %.3f seconds' % (fast_func_name, taken))
        if len(self._xpassed) > 0:
            self.write_center('xpassed tests', '_')
            for e in self._xpassed:
                self.write('%s: %s\n' % (e[0], e[1]))
            self.write('\n')
        if self._tb_style != 'no' and len(self._exceptions) > 0:
            for e in self._exceptions:
                filename, f, (t, val, tb) = e
                self.write_center('', '_')
                if f is None:
                    s = '%s' % filename
                else:
                    s = '%s:%s' % (filename, f.__name__)
                self.write_center(s, '_')
                self.write_exception(t, val, tb)
            self.write('\n')
        if self._tb_style != 'no' and len(self._failed) > 0:
            for e in self._failed:
                filename, f, (t, val, tb) = e
                self.write_center('', '_')
                self.write_center('%s::%s' % (filename, f.__name__), '_')
                self.write_exception(t, val, tb)
            self.write('\n')
        if self._tb_style != 'no' and len(self._failed_doctest) > 0:
            for e in self._failed_doctest:
                filename, msg = e
                self.write_center('', '_')
                self.write_center('%s' % filename, '_')
                self.write(msg)
            self.write('\n')
        self.write_center(text)
        ok = len(self._failed) == 0 and len(self._exceptions) == 0 and (len(self._failed_doctest) == 0)
        if not ok:
            self.write('DO *NOT* COMMIT!\n')
        return ok

    def entering_filename(self, filename, n):
        rel_name = filename[len(self._root_dir) + 1:]
        self._active_file = rel_name
        self._active_file_error = False
        self.write(rel_name)
        self.write('[%d] ' % n)

    def leaving_filename(self):
        self.write(' ')
        if self._active_file_error:
            self.write('[FAIL]', 'Red', align='right')
        else:
            self.write('[OK]', 'Green', align='right')
        self.write('\n')
        if self._verbose:
            self.write('\n')

    def entering_test(self, f):
        self._active_f = f
        if self._verbose:
            self.write('\n' + f.__name__ + ' ')

    def test_xfail(self):
        self._xfailed += 1
        self.write('f', 'Green')

    def test_xpass(self, v):
        message = str(v)
        self._xpassed.append((self._active_file, message))
        self.write('X', 'Green')

    def test_fail(self, exc_info):
        self._failed.append((self._active_file, self._active_f, exc_info))
        self.write('F', 'Red')
        self._active_file_error = True

    def doctest_fail(self, name, error_msg):
        error_msg = '\n'.join(error_msg.split('\n')[1:])
        self._failed_doctest.append((name, error_msg))
        self.write('F', 'Red')
        self._active_file_error = True

    def test_pass(self, char='.'):
        self._passed += 1
        if self._verbose:
            self.write('ok', 'Green')
        else:
            self.write(char, 'Green')

    def test_skip(self, v=None):
        char = 's'
        self._skipped += 1
        if v is not None:
            message = str(v)
            if message == 'KeyboardInterrupt':
                char = 'K'
            elif message == 'Timeout':
                char = 'T'
            elif message == 'Slow':
                char = 'w'
        if self._verbose:
            if v is not None:
                self.write(message + ' ', 'Blue')
            else:
                self.write(' - ', 'Blue')
        self.write(char, 'Blue')

    def test_exception(self, exc_info):
        self._exceptions.append((self._active_file, self._active_f, exc_info))
        if exc_info[0] is TimeOutError:
            self.write('T', 'Red')
        else:
            self.write('E', 'Red')
        self._active_file_error = True

    def import_error(self, filename, exc_info):
        self._exceptions.append((filename, None, exc_info))
        rel_name = filename[len(self._root_dir) + 1:]
        self.write(rel_name)
        self.write('[?]   Failed to import', 'Red')
        self.write(' ')
        self.write('[FAIL]', 'Red', align='right')
        self.write('\n')

