class CodeWrapError(Exception):
    pass

class CodeWrapper:
    _filename = 'wrapped_code'
    _module_basename = 'wrapper_module'
    _module_counter = 0

    @property
    def filename(self):
        return '%s_%s' % (self._filename, CodeWrapper._module_counter)

    @property
    def module_name(self):
        return '%s_%s' % (self._module_basename, CodeWrapper._module_counter)

    def __init__(self, generator, filepath=None, flags=[], verbose=False):
        self.generator = generator
        self.filepath = filepath
        self.flags = flags
        self.quiet = not verbose

    @property
    def include_header(self):
        return bool(self.filepath)

    @property
    def include_empty(self):
        return bool(self.filepath)

    def _generate_code(self, main_routine, routines):
        routines.append(main_routine)
        self.generator.write(routines, self.filename, True, self.include_header, self.include_empty)

    def wrap_code(self, routine, helpers=None):
        helpers = helpers or []
        if self.filepath:
            workdir = os.path.abspath(self.filepath)
        else:
            workdir = tempfile.mkdtemp('_sympy_compile')
        if not os.access(workdir, os.F_OK):
            os.mkdir(workdir)
        oldwork = os.getcwd()
        os.chdir(workdir)
        try:
            sys.path.append(workdir)
            self._generate_code(routine, helpers)
            self._prepare_files(routine)
            self._process_files(routine)
            mod = __import__(self.module_name)
        finally:
            sys.path.remove(workdir)
            CodeWrapper._module_counter += 1
            os.chdir(oldwork)
            if not self.filepath:
                try:
                    shutil.rmtree(workdir)
                except OSError:
                    pass
        return self._get_wrapped_function(mod, routine.name)

    def _process_files(self, routine):
        command = self.command
        command.extend(self.flags)
        try:
            retoutput = check_output(command, stderr=STDOUT)
        except CalledProcessError as e:
            raise CodeWrapError('Error while executing command: %s. Command output is:\n%s' % (' '.join(command), e.output.decode('utf-8')))
        if not self.quiet:
            print(retoutput)

class DummyWrapper(CodeWrapper):
    template = '# dummy module for testing of SymPy\ndef %(name)s():\n    return "%(expr)s"\n%(name)s.args = "%(args)s"\n%(name)s.returns = "%(retvals)s"\n'

    def _prepare_files(self, routine):
        return

    def _generate_code(self, routine, helpers):
        with open('%s.py' % self.module_name, 'w') as f:
            printed = ', '.join([str(res.expr) for res in routine.result_variables])
            args = filter(lambda x: not isinstance(x, OutputArgument), routine.arguments)
            retvals = []
            for val in routine.result_variables:
                if isinstance(val, Result):
                    retvals.append('nameless')
                else:
                    retvals.append(val.result_var)
            print(DummyWrapper.template % {'name': routine.name, 'expr': printed, 'args': ', '.join([str(a.name) for a in args]), 'retvals': ', '.join([str(val) for val in retvals])}, end='', file=f)

    def _process_files(self, routine):
        return

    @classmethod
    def _get_wrapped_function(cls, mod, name):
        return getattr(mod, name)

