__all__ = ['Routine', 'DataType', 'default_datatypes', 'get_default_datatype', 'Argument', 'InputArgument', 'OutputArgument', 'Result', 'CodeGen', 'CCodeGen', 'FCodeGen', 'JuliaCodeGen', 'OctaveCodeGen', 'RustCodeGen', 'codegen', 'make_routine']

class Routine:

    def __init__(self, name, arguments, results, local_vars, global_vars):
        input_symbols = set()
        symbols = set()
        for arg in arguments:
            if isinstance(arg, OutputArgument):
                symbols.update(arg.expr.free_symbols - arg.expr.atoms(Indexed))
            elif isinstance(arg, InputArgument):
                input_symbols.add(arg.name)
            elif isinstance(arg, InOutArgument):
                input_symbols.add(arg.name)
                symbols.update(arg.expr.free_symbols - arg.expr.atoms(Indexed))
            else:
                raise ValueError('Unknown Routine argument: %s' % arg)
        for r in results:
            if not isinstance(r, Result):
                raise ValueError('Unknown Routine result: %s' % r)
            symbols.update(r.expr.free_symbols - r.expr.atoms(Indexed))
        local_symbols = set()
        for r in local_vars:
            if isinstance(r, Result):
                symbols.update(r.expr.free_symbols - r.expr.atoms(Indexed))
                local_symbols.add(r.name)
            else:
                local_symbols.add(r)
        symbols = {s.label if isinstance(s, Idx) else s for s in symbols}
        notcovered = symbols.difference(input_symbols.union(local_symbols).union(global_vars))
        if notcovered != set():
            raise ValueError('Symbols needed for output are not in input ' + ', '.join([str(x) for x in notcovered]))
        self.name = name
        self.arguments = arguments
        self.results = results
        self.local_vars = local_vars
        self.global_vars = global_vars

    def __str__(self):
        return self.__class__.__name__ + '({name!r}, {arguments}, {results}, {local_vars}, {global_vars})'.format(**self.__dict__)
    __repr__ = __str__

    @property
    def variables(self):
        v = set(self.local_vars)
        v.update((arg.name for arg in self.arguments))
        v.update((res.result_var for res in self.results))
        return v

    @property
    def result_variables(self):
        args = [arg for arg in self.arguments if isinstance(arg, (OutputArgument, InOutArgument))]
        args.extend(self.results)
        return args

class DataType:

    def __init__(self, cname, fname, pyname, jlname, octname, rsname):
