        self.jlname = jlname
        self.octname = octname
        self.rsname = rsname
default_datatypes = {'int': DataType('int', 'INTEGER*4', 'int', '', '', 'i32'), 'float': DataType('double', 'REAL*8', 'float', '', '', 'f64'), 'complex': DataType('double', 'COMPLEX*16', 'complex', '', '', 'float')}
COMPLEX_ALLOWED = False

def get_default_datatype(expr, complex_allowed=None):
    if complex_allowed is None:
        complex_allowed = COMPLEX_ALLOWED
    if complex_allowed:
        final_dtype = 'complex'
    else:
        final_dtype = 'float'
    if expr.is_integer:
        return default_datatypes['int']
    elif expr.is_real:
        return default_datatypes['float']
    elif isinstance(expr, MatrixBase):
        dt = 'int'
        for element in expr:
            if dt == 'int' and (not element.is_integer):
                dt = 'float'
            if dt == 'float' and (not element.is_real):
                return default_datatypes[final_dtype]
        return default_datatypes[dt]
    else:
        return default_datatypes[final_dtype]

class Variable:

    def __init__(self, name, datatype=None, dimensions=None, precision=None):
        if not isinstance(name, (Symbol, MatrixSymbol)):
            raise TypeError('The first argument must be a SymPy symbol.')
        if datatype is None:
            datatype = get_default_datatype(name)
        elif not isinstance(datatype, DataType):
            raise TypeError("The (optional) `datatype' argument must be an instance of the DataType class.")
        if dimensions and (not isinstance(dimensions, (tuple, list))):
            raise TypeError('The dimensions argument must be a sequence of tuples')
