        self._datatype = {'C': datatype.cname, 'FORTRAN': datatype.fname, 'JULIA': datatype.jlname, 'OCTAVE': datatype.octname, 'PYTHON': datatype.pyname, 'RUST': datatype.rsname}
        self.dimensions = dimensions
        self.precision = precision

    def __str__(self):
        return '%s(%r)' % (self.__class__.__name__, self.name)
    __repr__ = __str__

    @property
    def name(self):
        return self._name

    def get_datatype(self, language):
        try:
            return self._datatype[language.upper()]
        except KeyError:
            raise CodeGenError('Has datatypes for languages: %s' % ', '.join(self._datatype))

