    __repr__ = __str__

class InOutArgument(Argument, ResultBase):

    def __init__(self, name, result_var, expr, datatype=None, dimensions=None, precision=None):
        if not datatype:
            datatype = get_default_datatype(expr)
        Argument.__init__(self, name, datatype, dimensions, precision)
        ResultBase.__init__(self, expr, result_var)
    __init__.__doc__ = OutputArgument.__init__.__doc__

    def __str__(self):
        return '%s(%r, %r, %r)' % (self.__class__.__name__, self.name, self.expr, self.result_var)
    __repr__ = __str__

class Result(Variable, ResultBase):

    def __init__(self, expr, name=None, result_var=None, datatype=None, dimensions=None, precision=None):
        if not isinstance(expr, (Basic, MatrixBase)):
            raise TypeError('The first argument must be a SymPy expression.')
        if name is None:
            name = 'result_%d' % abs(hash(expr))
        if datatype is None:
            datatype = get_default_datatype(expr)
        if isinstance(name, str):
            if isinstance(expr, (MatrixBase, MatrixExpr)):
                name = MatrixSymbol(name, *expr.shape)
            else:
                name = Symbol(name)
        if result_var is None:
            result_var = name
        Variable.__init__(self, name, datatype=datatype, dimensions=dimensions, precision=precision)
        ResultBase.__init__(self, expr, result_var)

    def __str__(self):
        return '%s(%r, %r, %r)' % (self.__class__.__name__, self.expr, self.name, self.result_var)
    __repr__ = __str__

class CodeGen:
    printer = None

    def _indent_code(self, codelines):
        return self.printer.indent_code(codelines)

    def _printer_method_with_settings(self, method, settings=None, *args, **kwargs):
        settings = settings or {}
        ori = {k: self.printer._settings[k] for k in settings}
        for k, v in settings.items():
            self.printer._settings[k] = v
