        for arg in routine.arguments:
            name = self.printer.doprint(arg.name)
            if arg.dimensions or isinstance(arg, ResultBase):
                type_args.append(('*%s' % name, arg.get_datatype('Rust')))
            else:
                type_args.append((name, arg.get_datatype('Rust')))
        arguments = ', '.join(['%s: %s' % t for t in type_args])
        return 'fn %s(%s)%s' % (routine.name, arguments, rstype)

    def _preprocessor_statements(self, prefix):
        code_lines = []
        return code_lines

    def _get_routine_opening(self, routine):
        prototype = self.get_prototype(routine)
        return ['%s {\n' % prototype]

    def _declare_arguments(self, routine):
        return []

    def _declare_globals(self, routine):
        return []

    def _declare_locals(self, routine):
        return []

    def _call_printer(self, routine):
        code_lines = []
        declarations = []
        returns = []
        dereference = []
        for arg in routine.arguments:
            if isinstance(arg, ResultBase) and (not arg.dimensions):
                dereference.append(arg.name)
        for result in routine.results:
            if isinstance(result, Result):
                assign_to = result.result_var
                returns.append(str(result.result_var))
            else:
                raise CodeGenError('unexpected object in Routine results')
            constants, not_supported, rs_expr = self._printer_method_with_settings('doprint', {'human': False, 'strict': False}, result.expr, assign_to=assign_to)
            for name, value in sorted(constants, key=str):
                declarations.append('const %s: f64 = %s;\n' % (name, value))
            for obj in sorted(not_supported, key=str):
                if isinstance(obj, Function):
                    name = obj.func
                else:
                    name = obj
                declarations.append('// unsupported: %s\n' % name)
            code_lines.append('let %s\n' % rs_expr)
        if len(returns) > 1:
            returns = ['(' + ', '.join(returns) + ')']
        returns.append('\n')
        return declarations + code_lines + returns

    def _get_routine_ending(self, routine):
        return ['}\n']

    def dump_rs(self, routines, f, prefix, header=True, empty=True):
        self.dump_code(routines, f, prefix, header, empty)
    dump_rs.extension = code_extension
    dump_rs.__doc__ = CodeGen.dump_code.__doc__
    dump_fns = [dump_rs]

def get_code_generator(language, project=None, standard=None, printer=None):
    if language == 'C':
        if standard is None:
            pass
        elif standard.lower() == 'c89':
            language = 'C89'
        elif standard.lower() == 'c99':
            language = 'C99'
    CodeGenClass = {'C': CCodeGen, 'C89': C89CodeGen, 'C99': C99CodeGen, 'F95': FCodeGen, 'JULIA': JuliaCodeGen, 'OCTAVE': OctaveCodeGen, 'RUST': RustCodeGen}.get(language.upper())
    if CodeGenClass is None:
        raise ValueError("Language '%s' is not supported." % language)
    return CodeGenClass(project, printer)

def codegen(name_expr, language=None, prefix=None, project='project', to_files=False, header=True, empty=True, argument_sequence=None, global_vars=None, standard=None, code_gen=None, printer=None):
    if language is None:
        if code_gen is None:
            raise ValueError('Need either language or code_gen')
    else:
        if code_gen is not None:
            raise ValueError('You cannot specify both language and code_gen.')
        code_gen = get_code_generator(language, project, standard, printer)
    if isinstance(name_expr[0], str):
        name_expr = [name_expr]
    if prefix is None:
        prefix = name_expr[0][0]
    routines = []
    for name, expr in name_expr:
        routines.append(code_gen.routine(name, expr, argument_sequence, global_vars))
    return code_gen.write(routines, prefix, to_files, header, empty)

def make_routine(name, expr, argument_sequence=None, global_vars=None, language='F95'):
    code_gen = get_code_generator(language)
    return code_gen.routine(name, expr, argument_sequence, global_vars)

