def threaded_factory(func, use_add):
    from sympy.core import sympify
    from sympy.matrices import MatrixBase
    from sympy.utilities.iterables import iterable

    @wraps(func)
    def threaded_func(expr, *args, **kwargs):
        if isinstance(expr, MatrixBase):
            return expr.applyfunc(lambda f: func(f, *args, **kwargs))
        elif iterable(expr):
            try:
                return expr.__class__([func(f, *args, **kwargs) for f in expr])
            except TypeError:
                return expr
        else:
            expr = sympify(expr)
            if use_add and expr.is_Add:
                return expr.__class__(*[func(f, *args, **kwargs) for f in expr.args])
            elif expr.is_Relational:
                return expr.__class__(func(expr.lhs, *args, **kwargs), func(expr.rhs, *args, **kwargs))
            else:
                return func(expr, *args, **kwargs)
    return threaded_func

def threaded(func):
    return threaded_factory(func, True)

def xthreaded(func):
    return threaded_factory(func, False)

def conserve_mpmath_dps(func):
    import mpmath

    def func_wrapper(*args, **kwargs):
        dps = mpmath.mp.dps
        try:
            return func(*args, **kwargs)
        finally:
            mpmath.mp.dps = dps
    func_wrapper = update_wrapper(func_wrapper, func)
    return func_wrapper

class no_attrs_in_subclass:

    def __init__(self, cls, f):
        self.cls = cls
        self.f = f

    def __get__(self, instance, owner=None):
        if owner == self.cls:
            if hasattr(self.f, '__get__'):
                return self.f.__get__(instance, owner)
            return self.f
