def is_palindromic(s, i=0, j=None):
    i, j, _ = slice(i, j).indices(len(s))
    m = (j - i) // 2
    return all((s[i + k] == s[j - 1 - k] for k in range(m)))

def flatten(iterable, levels=None, cls=None):
    from sympy.tensor.array import NDimArray
    if levels is not None:
        if not levels:
            return iterable
        elif levels > 0:
            levels -= 1
        else:
            raise ValueError('expected non-negative number of levels, got %s' % levels)
    if cls is None:

        def reducible(x):
            return is_sequence(x, set)
    else:

        def reducible(x):
            return isinstance(x, cls)
    result = []
    for el in iterable:
        if reducible(el):
            if hasattr(el, 'args') and (not isinstance(el, NDimArray)):
                el = el.args
            result.extend(flatten(el, levels=levels, cls=cls))
        else:
            result.append(el)
    return result

def unflatten(iter, n=2):
    if n < 1 or len(iter) % n:
        raise ValueError('iter length is not a multiple of %i' % n)
    return list(zip(*(iter[i::n] for i in range(n))))

def reshape(seq, how):
    m = sum(flatten(how))
    n, rem = divmod(len(seq), m)
    if m < 0 or rem:
        raise ValueError('template must sum to positive number that divides the length of the sequence')
    i = 0
    container = type(how)
    rv = [None] * n
    for k in range(len(rv)):
        _rv = []
        for hi in how:
            if isinstance(hi, int):
                _rv.extend(seq[i:i + hi])
                i += hi
            else:
                n = sum(flatten(hi))
                hi_type = type(hi)
                _rv.append(hi_type(reshape(seq[i:i + n], hi)[0]))
                i += n
        rv[k] = container(_rv)
    return type(seq)(rv)

def group(seq, multiple=True):
    if multiple:
        return [list(g) for _, g in groupby(seq)]
    return [(k, len(list(g))) for k, g in groupby(seq)]

def _iproduct2(iterable1, iterable2):
    it1 = iter(iterable1)
    it2 = iter(iterable2)
    elems1 = []
    elems2 = []
    sentinel = object()

    def append(it, elems):
        e = next(it, sentinel)
        if e is not sentinel:
            elems.append(e)
    n = 0
    append(it1, elems1)
    append(it2, elems2)
    while n <= len(elems1) + len(elems2):
        for m in range(n - len(elems1) + 1, len(elems2)):
            yield (elems1[n - m], elems2[m])
        n += 1
        append(it1, elems1)
        append(it2, elems2)

def iproduct(*iterables):
    if len(iterables) == 0:
        yield ()
        return
    elif len(iterables) == 1:
        for e in iterables[0]:
            yield (e,)
    elif len(iterables) == 2:
        yield from _iproduct2(*iterables)
    else:
        first, others = (iterables[0], iterables[1:])
        for ef, eo in _iproduct2(first, iproduct(*others)):
            yield ((ef,) + eo)

def multiset(seq):
    return dict(Counter(seq).items())

def ibin(n, bits=None, str=False):
    if n < 0:
        raise ValueError('negative numbers are not allowed')
    n = as_int(n)
    if bits is None:
        bits = 0
    else:
        try:
            bits = as_int(bits)
        except ValueError:
            bits = -1
        else:
            if n.bit_length() > bits:
                raise ValueError('`bits` must be >= {}'.format(n.bit_length()))
    if not str:
        if bits >= 0:
            return [1 if i == '1' else 0 for i in bin(n)[2:].rjust(bits, '0')]
        else:
            return variations(range(2), n, repetition=True)
    elif bits >= 0:
        return bin(n)[2:].rjust(bits, '0')
    else:
        return (bin(i)[2:].rjust(n, '0') for i in range(2 ** n))

def variations(seq, n, repetition=False):
    if not repetition:
        seq = tuple(seq)
        if len(seq) < n:
            return iter(())
        return permutations(seq, n)
    elif n == 0:
        return iter(((),))
    else:
        return product(seq, repeat=n)

def subsets(seq, k=None, repetition=False):
    if k is None:
        if not repetition:
            return chain.from_iterable((combinations(seq, k) for k in range(len(seq) + 1)))
        else:
            return chain.from_iterable((combinations_with_replacement(seq, k) for k in range(len(seq) + 1)))
    elif not repetition:
        return combinations(seq, k)
    else:
        return combinations_with_replacement(seq, k)

def filter_symbols(iterator, exclude):
    exclude = set(exclude)
    for s in iterator:
        if s not in exclude:
            yield s

def numbered_symbols(prefix='x', cls=None, start=0, exclude=(), *args, **assumptions):
    exclude = set(exclude or [])
    if cls is None:
        from sympy.core import Symbol
        cls = Symbol
    while True:
        name = '%s%s' % (prefix, start)
        s = cls(name, *args, **assumptions)
        if s not in exclude:
            yield s
        start += 1

def capture(func):
    from io import StringIO
    import sys
    stdout = sys.stdout
    sys.stdout = file = StringIO()
    try:
        func()
    finally:
        sys.stdout = stdout
    return file.getvalue()

def sift(seq, keyfunc, binary=False):
    if not binary:
        m = defaultdict(list)
        for i in seq:
            m[keyfunc(i)].append(i)
        return m
    sift = F, T = ([], [])
    for i in seq:
        try:
            sift[keyfunc(i)].append(i)
        except (IndexError, TypeError):
            raise ValueError('keyfunc gave non-binary output')
    return (T, F)

def take(iter, n):
    return [value for _, value in zip(range(n), iter)]

def dict_merge(*dicts):
    merged = {}
    for dict in dicts:
        merged.update(dict)
    return merged

def common_prefix(*seqs):
    if not all(seqs):
        return []
    elif len(seqs) == 1:
        return seqs[0]
    i = 0
    for i in range(min((len(s) for s in seqs))):
        if not all((seqs[j][i] == seqs[0][i] for j in range(len(seqs)))):
            break
    else:
        i += 1
    return seqs[0][:i]

def common_suffix(*seqs):
    if not all(seqs):
        return []
    elif len(seqs) == 1:
        return seqs[0]
    i = 0
    for i in range(-1, -min((len(s) for s in seqs)) - 1, -1):
        if not all((seqs[j][i] == seqs[0][i] for j in range(len(seqs)))):
            break
    else:
        i -= 1
    if i == -1:
        return []
    else:
        return seqs[0][i + 1:]

def prefixes(seq):
    n = len(seq)
    for i in range(n):
        yield seq[:i + 1]

def postfixes(seq):
    n = len(seq)
    for i in range(n):
        yield seq[n - i - 1:]

def topological_sort(graph, key=None):
    V, E = graph
    L = []
    S = set(V)
    E = list(E)
    S.difference_update((u for v, u in E))
    if key is None:

        def key(value):
            return value
    S = sorted(S, key=key, reverse=True)
    while S:
        node = S.pop()
        L.append(node)
        for u, v in list(E):
            if u == node:
                E.remove((u, v))
                for _u, _v in E:
                    if v == _v:
                        break
                else:
                    kv = key(v)
                    for i, s in enumerate(S):
                        ks = key(s)
                        if kv > ks:
                            S.insert(i, v)
                            break
                    else:
                        S.append(v)
    if E:
        raise ValueError('cycle detected')
    else:
        return L

def strongly_connected_components(G):
    V, E = G
    Gmap = {vi: [] for vi in V}
    for v1, v2 in E:
        Gmap[v1].append(v2)
    return _strongly_connected_components(V, Gmap)

def _strongly_connected_components(V, Gmap):
    lowlink = {}
    indices = {}
    stack = OrderedDict()
    callstack = []
    components = []
    nomore = object()

    def start(v):
        index = len(stack)
        indices[v] = lowlink[v] = index
        stack[v] = None
        callstack.append((v, iter(Gmap[v])))

    def finish(v1):
        if lowlink[v1] == indices[v1]:
            component = [stack.popitem()[0]]
            while component[-1] is not v1:
                component.append(stack.popitem()[0])
            components.append(component[::-1])
        v2, _ = callstack.pop()
        if callstack:
            v1, _ = callstack[-1]
            lowlink[v1] = min(lowlink[v1], lowlink[v2])
    for v in V:
        if v in indices:
            continue
        start(v)
        while callstack:
            v1, it1 = callstack[-1]
            v2 = next(it1, nomore)
            if v2 is nomore:
                finish(v1)
            elif v2 not in indices:
                start(v2)
            elif v2 in stack:
                lowlink[v1] = min(lowlink[v1], indices[v2])
    return components

def connected_components(G):
    V, E = G
    E_undirected = []
    for v1, v2 in E:
        E_undirected.extend([(v1, v2), (v2, v1)])
    return strongly_connected_components((V, E_undirected))

def rotate_left(x, y):
    if len(x) == 0:
        return []
    y = y % len(x)
    return x[y:] + x[:y]

def rotate_right(x, y):
    if len(x) == 0:
        return []
    y = len(x) - y % len(x)
    return x[y:] + x[:y]

def least_rotation(x, key=None):
    from sympy.functions.elementary.miscellaneous import Id
    if key is None:
        key = Id
    S = x + x
    f = [-1] * len(S)
    k = 0
    for j in range(1, len(S)):
        sj = S[j]
        i = f[j - k - 1]
        while i != -1 and sj != S[k + i + 1]:
            if key(sj) < key(S[k + i + 1]):
                k = j - i - 1
            i = f[i]
        if sj != S[k + i + 1]:
            if key(sj) < key(S[k]):
                k = j
            f[j - k] = -1
        else:
            f[j - k] = i + 1
    return k

def multiset_combinations(m, n, g=None):
    from sympy.core.sorting import ordered
    if g is None:
        if isinstance(m, dict):
            if any((as_int(v) < 0 for v in m.values())):
                raise ValueError('counts cannot be negative')
            N = sum(m.values())
            if n > N:
                return
            g = [[k, m[k]] for k in ordered(m)]
        else:
            m = list(m)
            N = len(m)
            if n > N:
                return
            try:
                m = multiset(m)
                g = [(k, m[k]) for k in ordered(m)]
            except TypeError:
                m = list(ordered(m))
                g = [list(i) for i in group(m, multiple=False)]
        del m
    else:
        N = sum((v for k, v in g))
    if n > N or not n:
        yield []
    else:
        for i, (k, v) in enumerate(g):
            if v >= n:
                yield ([k] * n)
                v = n - 1
            for v in range(min(n, v), 0, -1):
                for j in multiset_combinations(None, n - v, g[i + 1:]):
                    rv = [k] * v + j
                    if len(rv) == n:
                        yield rv

def multiset_permutations(m, size=None, g=None):
    from sympy.core.sorting import ordered
    if g is None:
        if isinstance(m, dict):
            if any((as_int(v) < 0 for v in m.values())):
                raise ValueError('counts cannot be negative')
            g = [[k, m[k]] for k in ordered(m)]
        else:
            m = list(ordered(m))
            g = [list(i) for i in group(m, multiple=False)]
        del m
    do = [gi for gi in g if gi[1] > 0]
    SUM = sum((gi[1] for gi in do))
    if not do or (size is not None and (size > SUM or size < 1)):
        if not do and size is None or size == 0:
            yield []
        return
    elif size == 1:
        for k, v in do:
            yield [k]
    elif len(do) == 1:
        k, v = do[0]
        v = v if size is None else size if size <= v else 0
        yield [k for i in range(v)]
    elif all((v == 1 for k, v in do)):
        for p in permutations([k for k, v in do], size):
            yield list(p)
    else:
        size = size if size is not None else SUM
        for i, (k, v) in enumerate(do):
            do[i][1] -= 1
            for j in multiset_permutations(None, size - 1, do):
                if j:
                    yield ([k] + j)
            do[i][1] += 1

def _partition(seq, vector, m=None):
    if m is None:
        m = max(vector) + 1
    elif isinstance(vector, int):
        vector, m = (m, vector)
    p = [[] for i in range(m)]
    for i, v in enumerate(vector):
        p[v].append(seq[i])
    return p

def _set_partitions(n):
    p = [0] * n
    q = [0] * n
    nc = 1
    yield (nc, q)
    while nc != n:
        m = n
        while 1:
            m -= 1
            i = q[m]
            if p[i] != 1:
                break
            q[m] = 0
        i += 1
        q[m] = i
        m += 1
        nc += m - n
        p[0] += n - m
        if i == nc:
            p[nc] = 0
            nc += 1
        p[i - 1] -= 1
        p[i] += 1
        yield (nc, q)

def multiset_partitions(multiset, m=None):
    if isinstance(multiset, int):
        n = multiset
        if m and m > n:
            return
        multiset = list(range(n))
        if m == 1:
            yield [multiset[:]]
            return
        for nc, q in _set_partitions(n):
            if m is None or nc == m:
                rv = [[] for i in range(nc)]
                for i in range(n):
                    rv[q[i]].append(multiset[i])
                yield rv
        return
    if len(multiset) == 1 and isinstance(multiset, str):
        multiset = [multiset]
    if not has_variety(multiset):
        n = len(multiset)
        if m and m > n:
            return
        if m == 1:
            yield [multiset[:]]
            return
        x = multiset[:1]
        for size, p in partitions(n, m, size=True):
            if m is None or size == m:
                rv = []
                for k in sorted(p):
                    rv.extend([x * k] * p[k])
                yield rv
    else:
        from sympy.core.sorting import ordered
        multiset = list(ordered(multiset))
        n = len(multiset)
        if m and m > n:
            return
        if m == 1:
            yield [multiset[:]]
            return
        elements, multiplicities = zip(*group(multiset, False))
        if len(elements) < len(multiset):
            if m:
                mpt = MultisetPartitionTraverser()
                for state in mpt.enum_range(multiplicities, m - 1, m):
                    yield list_visitor(state, elements)
            else:
                for state in multiset_partitions_taocp(multiplicities):
                    yield list_visitor(state, elements)
        else:
            for nc, q in _set_partitions(n):
                if m is None or nc == m:
                    rv = [[] for i in range(nc)]
                    for i in range(n):
                        rv[q[i]].append(i)
                    yield [[multiset[j] for j in i] for i in rv]

def partitions(n, m=None, k=None, size=False):
    if n <= 0 or (m is not None and m < 1) or (k is not None and k < 1) or (m and k and (m * k < n)):
        if size:
            yield (0, {})
        else:
            yield {}
        return
    if m is None:
        m = n
    else:
        m = min(m, n)
    k = min(k or n, n)
    n, m, k = (as_int(n), as_int(m), as_int(k))
    q, r = divmod(n, k)
    ms = {k: q}
    keys = [k]
    if r:
        ms[r] = 1
        keys.append(r)
    room = m - q - bool(r)
    if size:
        yield (sum(ms.values()), ms.copy())
    else:
        yield ms.copy()
    while keys != [1]:
        if keys[-1] == 1:
            del keys[-1]
            reuse = ms.pop(1)
            room += reuse
        else:
            reuse = 0
        while 1:
            i = keys[-1]
            newcount = ms[i] = ms[i] - 1
            reuse += i
            if newcount == 0:
                del keys[-1], ms[i]
            room += 1
            i -= 1
            q, r = divmod(reuse, i)
            need = q + bool(r)
            if need > room:
                if not keys:
                    return
                continue
            ms[i] = q
            keys.append(i)
            if r:
                ms[r] = 1
                keys.append(r)
            break
        room -= need
        if size:
            yield (sum(ms.values()), ms.copy())
        else:
            yield ms.copy()

def ordered_partitions(n, m=None, sort=True):
    if n < 1 or (m is not None and m < 1):
        yield []
        return
    if m is None:
        a = [1] * n
        y = -1
        v = n
        while v > 0:
            v -= 1
            x = a[v] + 1
            while y >= 2 * x:
                a[v] = x
                y -= x
                v += 1
            w = v + 1
            while x <= y:
                a[v] = x
                a[w] = y
                yield a[:w + 1]
                x += 1
                y -= 1
            a[v] = x + y
            y = a[v] - 1
            yield a[:w]
    elif m == 1:
        yield [n]
    elif n == m:
        yield ([1] * n)
    else:
        for b in range(1, n // m + 1):
            a = [b] * m
            x = n - b * m
            if not x:
                if sort:
                    yield a
            elif not sort and x <= m:
                for ax in ordered_partitions(x, sort=False):
                    mi = len(ax)
                    a[-mi:] = [i + b for i in ax]
                    yield a
                    a[-mi:] = [b] * mi
            else:
                for mi in range(1, m):
                    for ax in ordered_partitions(x, mi, sort=True):
                        a[-mi:] = [i + b for i in ax]
                        yield a
                        a[-mi:] = [b] * mi

def binary_partitions(n):
    from math import ceil, log2
    power = int(2 ** ceil(log2(n)))
    acc = 0
    partition = []
    while power:
        if acc + power <= n:
            partition.append(power)
            acc += power
        power >>= 1
    last_num = len(partition) - 1 - (n & 1)
    while last_num >= 0:
        yield partition
        if partition[last_num] == 2:
            partition[last_num] = 1
            partition.append(1)
            last_num -= 1
            continue
        partition.append(1)
        partition[last_num] >>= 1
        x = partition[last_num + 1] = partition[last_num]
        last_num += 1
        while x > 1:
            if x <= len(partition) - last_num - 1:
                del partition[-x + 1:]
                last_num += 1
                partition[last_num] = x
            else:
                x >>= 1
    yield ([1] * n)

def has_dups(seq):
    from sympy.core.containers import Dict
    from sympy.sets.sets import Set
    if isinstance(seq, (dict, set, Dict, Set)):
        return False
    unique = set()
    try:
        return any((True for s in seq if s in unique or unique.add(s)))
    except TypeError:
        return len(seq) != len(list(uniq(seq)))

def has_variety(seq):
    for i, s in enumerate(seq):
        if i == 0:
            sentinel = s
        elif s != sentinel:
            return True
    return False

def uniq(seq, result=None):
    try:
        n = len(seq)
    except TypeError:
        n = None

    def check():
        if n is not None and len(seq) != n:
            raise RuntimeError('sequence changed size during iteration')
    try:
        seen = set()
        result = result or []
        for i, s in enumerate(seq):
            if not (s in seen or seen.add(s)):
                yield s
                check()
    except TypeError:
        if s not in result:
            yield s
            check()
            result.append(s)
        if hasattr(seq, '__getitem__'):
            yield from uniq(seq[i + 1:], result)
        else:
            yield from uniq(seq, result)

def generate_bell(n):
    n = as_int(n)
    if n < 1:
        raise ValueError('n must be a positive integer')
    if n == 1:
        yield (0,)
    elif n == 2:
        yield (0, 1)
        yield (1, 0)
    elif n == 3:
        yield from [(0, 1, 2), (0, 2, 1), (2, 0, 1), (2, 1, 0), (1, 2, 0), (1, 0, 2)]
    else:
        m = n - 1
        op = [0] + [-1] * m
        l = list(range(n))
        while True:
            yield tuple(l)
            big = (None, -1)
            for i in range(n):
                if op[i] and l[i] > big[1]:
                    big = (i, l[i])
            i, _ = big
            if i is None:
                break
            j = i + op[i]
            l[i], l[j] = (l[j], l[i])
            op[i], op[j] = (op[j], op[i])
            if j == 0 or j == m or l[j + op[j]] > l[j]:
                op[j] = 0
            for i in range(j):
                if l[i] > l[j]:
                    op[i] = 1
            for i in range(j + 1, n):
                if l[i] > l[j]:
                    op[i] = -1

def generate_involutions(n):
    idx = list(range(n))
    for p in permutations(idx):
        for i in idx:
            if p[p[i]] != i:
                break
        else:
            yield p

def multiset_derangements(s):
    from sympy.core.sorting import ordered
    try:
        ms = multiset(s)
    except TypeError:
        key = dict(enumerate(ordered(uniq(s))))
        h = []
        for si in s:
            for k in key:
                if key[k] == si:
                    h.append(k)
                    break
        for i in multiset_derangements(h):
            yield [key[j] for j in i]
        return
    mx = max(ms.values())
    n = len(s)
    if mx * 2 > n:
        return
    if len(ms) == n:
        yield from _set_derangements(s)
        return
    for M in ms:
        if ms[M] == mx:
            break
    inonM = [i for i in range(n) if s[i] != M]
    iM = [i for i in range(n) if s[i] == M]
    rv = [None] * n
    if 2 * mx == n:
        for i in inonM:
            rv[i] = M
        for p in multiset_permutations([s[i] for i in inonM]):
            for i, pi in zip(iM, p):
                rv[i] = pi
            yield rv
        rv[:] = [None] * n
        return
    if n - 2 * mx == 1 and len(ms.values()) == n - mx + 1:
        for i, i1 in enumerate(inonM):
            ifill = inonM[:i] + inonM[i + 1:]
            for j in ifill:
                rv[j] = M
            for p in permutations([s[j] for j in ifill]):
                rv[i1] = s[i1]
                for j, pi in zip(iM, p):
                    rv[j] = pi
                k = i1
                for j in iM:
                    rv[j], rv[k] = (rv[k], rv[j])
                    yield rv
                    k = j
        rv[:] = [None] * n
        return

    def finish_derangements():
        a = take[1][0]
        a_ct = take[1][1]
        b = take[0][0]
        b_ct = take[0][1]
        forced_a = []
        forced_b = []
        open_free = []
        for i in range(len(s)):
            if rv[i] is None:
                if s[i] == a:
                    forced_b.append(i)
                elif s[i] == b:
                    forced_a.append(i)
                else:
                    open_free.append(i)
        if len(forced_a) > a_ct or len(forced_b) > b_ct:
            return
        for i in forced_a:
            rv[i] = a
        for i in forced_b:
            rv[i] = b
        for a_place in combinations(open_free, a_ct - len(forced_a)):
            for a_pos in a_place:
                rv[a_pos] = a
            for i in open_free:
                if rv[i] is None:
                    rv[i] = b
            yield rv
            for i in open_free:
                rv[i] = None
        for i in forced_a:
            rv[i] = None
        for i in forced_b:
            rv[i] = None

    def iopen(v):
        return [i for i in range(n) if rv[i] is None and s[i] != v]

    def do(j):
        if j == 1:
            yield from finish_derangements()
        else:
            M, mx = take[j]
            for i in combinations(iopen(M), mx):
                for ii in i:
                    rv[ii] = M
                yield from do(j - 1)
                for ii in i:
                    rv[ii] = None
    take = sorted(ms.items(), key=lambda x: (x[1], x[0]))
    yield from do(len(take) - 1)
