def random_derangement(t, choice=None, strict=True):
    if choice is None:
        import secrets
        choice = secrets.choice

    def shuffle(rv):
        for i in range(len(rv) - 1, 0, -1):
            x = choice(rv[:i + 1])
            j = rv.index(x)
            rv[i], rv[j] = (rv[j], rv[i])

    def pick(rv, n):
        shuffle(rv)
        return rv[:n]
    ms = multiset(t)
    tot = len(t)
    ms = sorted(ms.items(), key=lambda x: x[1])
    M, mx = ms[-1]
    n = len(t)
    xs = 2 * mx - tot
    if xs > 0:
        if strict:
            raise ValueError('no derangement possible')
        opts = [i for i, c in enumerate(t) if c == ms[-1][0]]
        pick(opts, xs)
        stay = sorted(opts[:xs])
        rv = list(t)
        for i in reversed(stay):
            rv.pop(i)
        rv = random_derangement(rv, choice)
        for i in stay:
            rv.insert(i, ms[-1][0])
