    if n == len(ms):
        rv = list(t)
        while True:
            shuffle(rv)
            if all((i != j for i, j in zip(rv, t))):
                break
    else:
        rv = [None] * n
        while True:
            j = 0
            while j > -len(ms):
                j -= 1
                e, c = ms[j]
                opts = [i for i in range(n) if rv[i] is None and t[i] != e]
                if len(opts) < c:
                    for i in range(n):
                        rv[i] = None
                    break
                pick(opts, c)
                for i in range(c):
                    rv[opts[i]] = e
