def _get_srepr(expr):
    s = srepr(expr)
    s = re.sub("WildDot\\('(\\w+)'\\)", '\\1', s)
    s = re.sub("WildPlus\\('(\\w+)'\\)", '*\\1', s)
    s = re.sub("WildStar\\('(\\w+)'\\)", '*\\1', s)
