from functools import wraps

def recurrence_memo(initial):
    cache = initial

    def decorator(f):

        @wraps(f)
        def g(n):
            L = len(cache)
            if n < L:
                return cache[n]
            for i in range(L, n + 1):
                cache.append(f(i, cache))
            return cache[-1]
        g.cache_length = lambda: len(cache)
        g.fetch_item = lambda x: cache[x]
        return g
    return decorator

def assoc_recurrence_memo(base_seq):
    cache = []

    def decorator(f):

        @wraps(f)
        def g(n, m):
            L = len(cache)
            if n < L:
                return cache[n][m]
            for i in range(L, n + 1):
                F_i0 = base_seq(i)
                F_i_cache = [F_i0]
                cache.append(F_i_cache)
                for j in range(1, i + 1):
                    F_ij = f(i, j, cache)
                    F_i_cache.append(F_ij)
            return cache[n][m]
        return g
    return decorator

